INSERT INTO `locales_quest` (`entry`, `Title_loc4`) VALUES (40057, '回收工匠火花应答器') ON DUPLICATE KEY UPDATE `Title_loc4` = VALUES(`Title_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`) VALUES (40072, '艾伦托家族价值') ON DUPLICATE KEY UPDATE `Title_loc4` = VALUES(`Title_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`) VALUES (40109, '过去的伤疤') ON DUPLICATE KEY UPDATE `Title_loc4` = VALUES(`Title_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`) VALUES (40177, '弗朗兹旺格曲柄') ON DUPLICATE KEY UPDATE `Title_loc4` = VALUES(`Title_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`) VALUES (40204, '与阿迪那的会面') ON DUPLICATE KEY UPDATE `Title_loc4` = VALUES(`Title_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`) VALUES (40264, '莫尔奥格危机') ON DUPLICATE KEY UPDATE `Title_loc4` = VALUES(`Title_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`) VALUES (40266, '莫尔奥格危机III') ON DUPLICATE KEY UPDATE `Title_loc4` = VALUES(`Title_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`) VALUES (41054, '耻辱不再') ON DUPLICATE KEY UPDATE `Title_loc4` = VALUES(`Title_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3861, '“咕咕嘎……咕咕嘎……咕咕！$B$B咕咕嘎……咕咕嘎……咕咕。”$B$B小鸡抬头看着你，然后伸出爪子探到地面上。你认为它是在拼写某个单词，但是又不确定是什么单词。S—A—L—D—E—A—N…C—o—o—C—e—l—y…是指萨丁农场吗？在你发出询问之前，小鸡转过身子，做它自己的事儿去了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4062, 'G。L。A。$B$B那些碎片上刻着这样的文字。在这些大写字母下面有一个军衔标志。你在燃烧平原所摧毁的机器的等级是四，我相信这是个比较低的军衔。$B$B把这块碎片样品交给东边一处营地里的鲁特维尔·沃拉图斯吧，他是个著名的元素学者，应该能对我们的研究有所帮助。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4132, '迄今为止你一直表现得很好，$N。现在你应该去完成你的最后一个任务了。$B$B黑铁矮人中的安格弗将军负责策划了对K。E。F。109师的攻击，并残杀我们的无数士兵——正义必须得到伸张！$B$B这无疑是一个极端艰难的任务，但是成功之后，你也会获得丰厚的奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4982, '在夜里，当这个地方守备松懈的时候，我就会在城里偷偷地四处走动，记下我所看到的可能会对K。E。F。有战略价值的任何东西。$B$B然而昨晚事情变得非常糟糕，我被一张网绊到并触动了一个机关，我马上把我的侦察装置藏起来去找藏身之所了！不幸的是，我没法取回那套装置。他们已经把巡逻兵的数量增加了两三倍！所有的情报都丢失了。$B$B把我的东西拿回来，我就可以返回K。E。F。去了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4983, '把这份报告交给雷克斯洛特。它可以让我恢复好名声，并且肯定会让K.E.F.在对付这些兽人时占据战略上的优势。$B$B跟你一起回去？我有太多的工作要做。快走吧，他们急需这些报告！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (6961, '冬幕节快乐，我的朋友！你一定要去冬天爷爷打个招呼！如果你今年表现的不错的话，你会在冬幕节那天收到一份很棒的礼物。你一定要告诉冬天爷爷你今年想要什么！$B$B另外，记得多买些好东西来给那些今年表现得好的人。我们这里货物齐全。各种货物一应俱全——这是烟林牧场精心为您准备的货物！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7604, '签署下面这份契约者担保他们交给瑟银兄弟会（TBLtd。）的萨弗隆铁锭是真品，绝非伪造。签署这份契约还将使瑟银兄弟会不对因签署者个人试图铸造、寻找、创造、销售或食用萨弗拉斯而造成的一切不良后果负有任何责任。$B$B签署这份契约即表明你同意以上所有条款。$B$B签名：_________________') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8730, '勇士，是你吗？我受命保管这个碎片已经一千年了，在我最黑暗的时候，应该有人站出来替我把它拿回来……但是一切都是任重道远的。$B$B<瓦拉斯塔兹轻轻地咳嗽着。>$B$B耐……耐法里奥斯现在掌握着节杖碎片。$B$B时间是最关键的。耐法里奥斯将要摧毁这个节杖。你必须赶快！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8740, '许多幕光之锤的骑兵教徒经常在我们塞纳里奥要塞守卫范围之外的区域游荡，并伺机袭击我们巡逻和商旅小队。$B$B找到并击败暮光掠夺者和他们的领袖，一个叫做莫娜的恐怖战士。当任务完成之后向唤风者梅恩·长角报告。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (20002, '<提里奥默默地检查了一会儿球体>$B以圣光之名！$B这个纯净的本质，这个光的原始能量，这绝对是亚历山德罗斯本人！$B他休眠的灵魂变成了这个球体，但目的是什么？$b我无法理解这一点，但也许我们可以试着唤醒他。我不确定这里的用词是否正确。但我们怎么能做到呢？$B熟悉的东西可能会起作用。$B听$n。赛丹·达索汉是最早的圣骑士之一，我和亚历山德罗斯的朋友，在某个时候他疯了。这在当时被证明是由于某种恶魔的影响。$B当雷诺杀死他的父亲时，赛丹拿走了灰烬使者的披风作为战利品。$b同时，如果我的信息是正确的，瑞文戴尔男爵骄傲地穿着亚历山德罗斯的斗篷作为嘲弄。$B你的任务是冒险进入斯坦索姆，找到这些曾经属于灰烬使者的物品。带上宝球，我相信你会有反应的。在此期间，我会努力理解这种情况。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (20005, '在我离开尘世的躯壳之后，光向我展示了许多不同的东西。$B我的生活，我的使命，我的未来。$b我现在全部的希望就是终结血色十字军。$b布丽奇特·阿比迪斯已经撤退到血色修道院。她下令招募更多的人，并设计了一种新的混合物，可以立即消灭不死生物。$B从她决定躲在房间里冥想的那天起，她的计划似乎就没有生效。你看，光有它自己的路径，对我们来说很神秘。她是为了一个愚蠢的目的而拥有更多的权力。在提尔之手的东边，血色十字军准备向北进发，等待他们的领袖回来，这样他们就可以开始了。$B但在她冥想期间，一股黑暗力量渗透进了修道院，并永远折磨着已经狂热的头脑。$B他们再也看不出活人和亡灵之间的区别了。他们对暗影魔法的使用来自一种不同的力量，一种可以等同于光本身的力量。$b是时候决定你是否准备好证明自己的勇气了。$B纳克萨玛斯确实是一个威胁，但这里的力量可以很好地超越那里。你准备好了吗$n？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39000, '来吧，伙计们，看，维兹洛的魔力——嗯哼……雾机！$B$B   $B$呸，潜在客户！你一定是从世界各地来看我的机器创造的奇迹。$B$B否？哦，好吧，没关系。那一定是缘分！或者你所信仰的神把你带到我面前。听着，这台机器可以创造奇迹，孩子。它可以扩展你的身体和精神能力。$B$B您只需在其中插入黄金即可使其正常工作！那么，你怎么说？支付十金激活它。当然，我需要340个，因为……材料，是的，材料！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39991, '我很高兴你决定加入我们$N。我听说过你在这个领域所做的工作，我必须说我印象深刻。你正是我们这个组织所需要的那种积极性很高的人。$B$B如果我们要长期守住这座城堡，我们必须确保我们的补给线。我想让你伏击那个混蛋瓦罗卡尔并彻底结束他的巡逻。他有警卫陪同，所以要小心，甚至可以带另一名特工来协助你，但一定要完成！在他死之前不要回到我身边。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39997, '现在是时候去取刀片的材料了。正如你所期望的那样，这不会是一个由金属制成的传统刀片。它将由石头制成，但不是任何普通的石头。真正让人类感到恐惧的东西。$B$B前往雷霆崖，与传送门大师比尔吉特·克兰斯顿交谈。她会帮你找到我们需要的特殊宝石。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40001, '啊，地球母亲的祝福，$R。$B$B是不是很棒？在这里，在大自然的包围下。$B$B   $B$B不是好东西，一点也不。$B$B说，你能帮我个忙吗？$B$bi我在等包裹，但包裹还没到。你能不能去和森金村的米什基核实一下，看看我的快递发生了什么事？$B$B') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40002, '所以，我派了一个普通的信使把好东西送到莫高雷那里，但是，你看，那个脾气暴躁的兽人骑着他的狼在杜隆塔尔附近报告说看到他死了，而我的草药不见了！$B$B那些野猪人们比平时更具侵略性，如果他们从大路上杀死我的信使！$B$B我的意思是，杜隆塔尔也不安全了。如果你不注意，这里的一切都会要了你的命。$B$B我打赌他们在杀死信使后拿走了他的背包，并把它带回了他们的营地，或者他们甚至把它带在了他们身上！$B$B试图杀死一些他们的侦察兵。如果你找到了大背包，把它带给煞古，你自己问他要钱！$B$B安全旅行，伙计，让洛阿指引你的脚步。$B$B<米什基说话时带着满口的巨魔口音，让他的通用语很难懂。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40015, '到目前为止，你做得很好，但最大的平原狼蛛站在你面前，$C。枯木巨魔一直在收集蜘蛛的毒液，因为它在食物中加入了魔酒，让蜘蛛睡着了。$B$B贺凯斯是一个可怕的敌人，许多巨魔已经倒下了，所以保持头脑清醒！你可以在格沙克农场的西边找到大蜘蛛。$B$B找到她，终结枯木强大毒液的来源！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40017, '事情现在可能很平静，但我们和枯木之间的战争还没有结束。当他们从最初的攻击中恢复过来时，我们必须为他们最终下山做好准备。$B$B尹多命令我为即将到来的战斗制造尽可能多的盔甲，但我的补给有限。从山上向南走，收集阿拉希迅猛龙的皮革，用来制造特别坚固的盔甲。$B$B该地区没有比迅猛龙更强壮的生物了。你一定要快。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40020, '当我们逃离祖尔拉萨兹的混乱时，我的许多人不得不留下珍贵的财物和其他具有个人价值的物品。我也不例外。我很惭愧地说，我放弃了一个护身符，这个护身符自上一个伟大帝国时代以来就在我家代代相传。$B$B它困扰着我的思想，$C。如果我不弥补这个巨大的耻辱，灵魂将永远不会再回应我的召唤。你必须为我找回它！祖尔拉萨兹废墟可以通过镇外的小径向西北方向进入。我的家在废墟城市的顶端附近。$B$B我可以自己去，但我不能因为这种自私的原因而冒生命危险。我向你保证，你的帮助会得到回报的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40021, '帝国灭亡后，我的人民逃到了我们世代繁荣的山区，与当地的元素保持积极的关系，并培养他们的成长。$B$B我们不知道我们中的一个人已经堕落到了威瑟巴克对权力的贪欲的堕落中。背叛了帝国的记忆，他们袭击了祖拉萨兹，在床上屠杀了我的人民。$B$B演讲者甘图，一个我曾经称之为朋友的人，对这场悲剧负有责任。为了我的人民，你要去祖拉撒兹的废墟，杀死他。为那些那天没能参加战斗的人伸张正义，$C。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40025, '从甘基的评论来看，这些护腕似乎已经损坏了。有人正在利用我们被削弱的地位，把我的同类变成邪恶的爪牙。我们必须清除这些护腕的污点，为此，我需要天然材料。$B$B你可以在这个世界上找到他们，他们应该在净化污点方面做得很好。带给演讲者甘基五个活根草，十块坚固的石头和三朵野钢花。他将为我准备材料。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40027, '我们来自一个地狱般的世界。一个充满危险，充满恶魔，以各种你可以想象的方式对所有生命充满恶意的地方。食物很少，水更少。我带领我的人民通过我们的魔法穿过裂缝到达这个世界的安全地带。在古代，我的人民创造了一种符咒，使他们适应旧世界，它拥有巨大的魔力。这使得我们可以进行长途旅行。$B$B我们现在失去了很多这种技能。从老一辈告诉我的故事来看，它比我们现在使用的原始手段要强大得多。$B$B桑维护身符是一件强大的物品，在我去迷雾谷的一次旅行中丢失了。我一直在尝试与一个来自避难所的裂缝探索者交流。当我试图在山谷中交流时，沼泽行者靠近并攻击了我。我没办法带着符咒，所以我把它留在一个小箱子里，然后逃命。给我拿来。这是非常重要的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40030, '有一个令我们恐惧的存在。他的名字是木棒诺博鲁，他和一群暴徒一起游荡，他们一有机会就恐吓我们。他是我们外域古老部落的一名熟练的战士。村里很少有人能同时对抗他和他的手下。诺博鲁在港口实施了巨大的暴行，杀害了我们部族的成员，没有任何悔恨的迹象。$B$B诺博鲁必须被阻止。你必须杀了他才能结束流血。他挥舞着一根棍棒，正是由于这种残忍的武器，他获得了他的绰号。打败他，把他的武器带给我们，这样我们才能在这个陌生的世界生存下去。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40032, '阿赫·扎多尔是一个裂缝探索者，他带领我们来到这个世界。他是我们种族中少数知道远古祖先魔法的人之一。在其他较小的裂谷探索者的帮助下，他有足够的技巧把我们整个部落和休耕保护区带到这里。$B$ba几周前，他试图返回旧世界，寻找更多的流亡者带到港口。我怀疑出了什么严重的问题，因为我无法察觉他在我们旧世界的存在。你看，他使用的魔法是旧的，而且有些不稳定。我们几乎不了解它的用法，只有像阿克资阿多这样聪明的人才能操纵它去旅行。$B$bi需要你收集材料，以便施放一个咒语来找到他的位置，并看看他可能去了哪里。当地的材料应该可以很好地工作。从东方的纠结恐怖中收集六个纠结的精华，从海岸的鱼人中收集一个沼泽鱼眼。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40033, '我的体力耗尽了。我感到衰老和虚弱，但我看到了一座城市。一座被淹没在波涛之下的城市，仿佛潮水自己来了，把一切都淹没了。那里有高大的悬崖，规模巨大，似乎那里的灵魂在痛苦中打滚。红色的树叶从树上落下，一种强烈的魔力在徘徊和跳动，仿佛它想让我离开。它削弱了我的力量，让我很难集中注意力。$B$bi我确信阿克资阿多现在就在这个世界上。他一定是在外域遇到了什么事情，被迫离开了。这一点，或者说他的裂缝的不稳定性，把他送到了这片异国的土地上。$B$B这是我所能记得的全部，局外人。似乎住在那里的东西都很强壮——比这里的野生动物强壮得多。比你强壮多了。我恳求你，无论阿赫·扎多尔在哪里，无论你花多长时间，都要设法找到他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40036, '雷瑟斯的侍从在深波下的雷瑟斯圣所的石头上立下了神圣的誓言。他们的话是他们的契约，但他们违背了他们清晰的言辞和他们承诺遵守的誓言。我们的任务是保护潮汐女王瑞舍尔，并为所有纳迦的更大利益严格执行她的奇思妙想和计划。$B$B当恶鞭被创造出来，分裂开始时，所有的侍从都改变了立场。他们在纳兹扎的命令下背叛了那些忠于雷瑟斯誓言的人，并在破碎海岸杀死了许多我最信任的兄弟。$B$B我想要他们死，外來者。我想让他们的尸体被深渊享用。从他们的身体上取下他们的军团印戒——一枚在他们宣誓时给他们的戒指。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40038, '风暴湾的首领是一只鱼人，它的大脑只有小牡蛎那么大。呣啦哇啦是他的名字。他应该受到残酷的惩罚，因为他把风暴湾鱼人召集起来进行公开反抗。$B$B你会发现黏糊糊的鳗鱼沿着南岭海滩的海岸线穿过小路向北游去。把他的头带给我，向他的其他走狗表明，潮汐女主人拉沙尔指挥着风暴湾鱼群。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40039, '雷瑟斯潮汐权杖在世界的深处为我掌握着力量，尤其是在纳扎塔尔。这是雷瑟斯与生俱来的权利，它赋予我们对其他许多人的统治权。我曾怀疑他们会试图偷走它，当恶鞭成立时，以获得这个统治权。$B$B您可能想知道我为什么要告诉您这些。像你这样的陆地生物永远不会担心。好吧，我把权杖埋在一个秘密的地方，这样他们就永远不能合法地获得权力。现在雷瑟斯圣地已经建立，我们也没有直接的危险，我希望它能归还给我。$B$B有一个叫做艾尔达拉塔的地方，由某个上层精灵守护者掌管。它位于半岛的最东北端。在它的西边，沿着海岸，有四块岩石。埋在这些岩石周围的是雷瑟斯潮汐权杖。得到它并把它带给我，闯入者，帮助我收回我与生俱来的权利。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40040, '好啊！欢迎来到亚麻须邮报。我是芬多，负责这里所有的事情。我应该把任何新来的亚麻须的人交给老板。也就是说，我们已经几个月没有听到诺莫瑞根的消息了，也没有收到任何新的人。不过，很高兴有你在身边，$R。你会在里面找到吉格诺·麻须，在顶楼。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40041, '如果你是真正的交易，那么你必须做一个真正的任务。有道理，对吧？一段时间以来，我一直渴望得到一只雾翼号角。这些生物非常强大，充满了各种自然能量。一段时间以来，我一直怀疑雾翼号角的用处可能超出了它的实际用途，我想对它进行测试。这就是你进来的地方。$B$B雾翼游荡者们位于西北方向，就在门纳尔湖旁边。不过要小心。那里有各种各样强大的东西！艾萨拉确实是个危险的地方。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40043, '在你回到麻须前线之前，我想请你帮我送一封信。它是关于一个机器人的，麻须前线已经在该地区运营了一段时间。我帮助它在艾萨拉内部探测魔法，几周前我在去雷瑟斯圣所的旅途中发现了它。它无可救药地陷入了某种年久失修的状态，残缺不全，毫无生机。$B$B吉格诺肯定至少想知道它发生了什么。把这封信交给他，$N，并再次感谢你的补给。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40044, '如果分析器53G仍然存在，那么这是一个好消息！我们在它的分析芯片上花了很长时间，几乎不可能重新制作。我们第一次拥有了布罗姆利的魔力，没有它，我无法完全复制它。$B$B雷瑟斯圣地就位于这里的东部，沿着海岸。纳迦居住在那里，他们对我们不是最友好的。我不想让我的船员冒险去拿分析芯片。你会发现它正好位于主底盘后侧抑制室的排气口下方，很容易。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40046, '丁考·托格派普——他在远东一个小岛上的停机坪上。$B$B我们将该停机坪用作加油区和飞行员休息点。我们过去常常在飞机燃料使用接近尾声时将它们分散在大洋中。以前从诺莫瑞根到卡利姆多是可以轻松到达的，但我觉得停机坪年久失修。我们已经很久没有听到家乡的消息了。$B$B如果你想要飞行日志，去丁考·托格派普那里拿。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40047, '麻须前线是由诺莫瑞根创立的，目的是利用艾萨拉的魔法力量在国外推进侏儒工程，并试图取得突破GHS！我们得到了一个工匠火花应答器，它被设计用来在我们的装置中利用魔法能量，尽管这个装置很久以前就被纳迦丢失了。我们已经等了好几个月了。$B$B我失去了船员，也没有诺莫瑞根的补给，我别无选择，只能去了解那里发生了什么。为什么一切都这么晚？$B$B查找工匠大师过火花。他应该在诺莫瑞根，除非有什么可怕的灾难毁了这座城市！他通常在顶层的工程部门工作。赶快把这份报告带给他！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40048, '我真的很震惊，我收到了来自麻须前线的回复。我以为他们已经知道在诺莫瑞根发生了什么。诺莫瑞根的崩溃几乎摧毁了我们所有的后勤工作，我们不可能帮助他们摆脱困境。$B$bi要你把这封信寄给吉格诺。我在里面放了一些硬币，用来资助艾萨拉的侏儒们的回程。确保他拿到这个。它包含了他所需要的所有信息，让他了解发生的最新情况。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40057, '现在我们知道诺莫瑞根被摧毁了，而且没有办法得到新的工匠火花应答器，我们必须收回我们的旧应答器。纳迦在几个月前偷走了它，我们必须拥有它才能在这里取得进展。$B$B没有办法回到诺莫瑞根，所以我们必须利用艾萨拉这里的东西，我知道那些该死的纳迦仍然拥有它！领导这次袭击的人叫拉斯赞，是个可怕的敌人。如果你想有机会，我建议你带些朋友来。这可能是你永远杀死他的唯一方法！$B$B他应该在埃尔达拉斯遗址的东面，沿着海岸线。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40065, '既然吉格诺已经为你担保，我想在这里做一些真正的工作。涡轮增压稳定冷却盘是我发明的。它帮助我们阅读艾萨拉的魔法和魔网等级。我们有一段时间过得很好，直到几个月前所有的纳加和鱼人都出现了！$B$B他们把我们从我们的网站赶走，我不得不放弃冷却盘，否则我肯定会失去我的生命，从他们手中撬开它。我想让你把它拿回来继续我的工作，而不是从头开始。冷却盘是我在诺莫瑞根制作的东西，我的许多计划仍然留在那里。$B$B东边是雷瑟斯纳迦们的避难所。如果你往圣所的北面走，会看到一个有点像迷宫的峡谷。在那个峡谷里，有一个洞穴。你会在那个洞穴里找到一个控制面板。在控制面板内部搜索涡轮增压稳定冷却盘。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40067, '谢谢你得到了这一切。现在我可以开始工作了。我的……在哪里？$B$B$B$B哈哈，我身上没有扳手。你能看看里面吗？如果有的话，它应该在二楼我的工具箱里。一旦我有了它，我就会开始。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40074, '看，圣骑士加纳苏斯不久前征用了一些剑，虽然他付钱让我做剑，我一直找不到交付它们的方法。拥有合适材料的最近的铁匠在夜色镇。$B$B克拉莉斯·纳尔特里被雇来为悲伤卫士制作剑。你会在那里找到她的。你能去夜色镇帮我收集剑吗？他们肯定会帮助减轻我的手工负担，让你给我们的铸锭走得更远。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40076, '我在悲伤卫士管理物资，让我告诉你，我们正在接近配给。我们保存和管理我们的供应，我确保我们对大多数东西都有一个锁定，但我们缺少的一样东西是食物。如果你能帮我在接下来的时间里即兴发挥，那肯定意义重大。$B$B该地区的美洲虎可能是最接近一顿像样的饭的东西。为我收集五个重型美洲虎侧翼。他们应该做得足够好，让每个人都吃饱。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40077, '你好，搭档！在这里看不到很多新面孔，尤其是在这座破旧的城堡里。你肯定听说过勇敢的防御者在被消灭前连续几天抵挡兽人的谣言吧！多好的故事。我也可以告诉你关于悲伤沼泽中的蘑菇的故事，尤其是销魂苔藓菇！$B$B销魂苔藓菇只生长在这个区域内。他们有一定的。。一旦你弄清楚如何正确地烹饪它们，你就会“品尝”它们——因为如果你不这样做，那就是致命的！我有几个朋友来自我的老家，他们很想尝试一下。你会像个朋友一样帮我拿到它们，对吗？$B$B我只需要十个。那应该很简单，搭档！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40079, '自第一次战争前建造以来，悲伤卫士就一直屹立不倒。虽然兽人在那场战争中摧毁了它，但城墙仍然屹立不倒。当然，这要归功于守望圣骑加纳苏斯。如果没有他努力将劳动力带到这里并进行维修，这个地方将只不过是一片阴燃的废墟。$B$B正是有了对过去的了解，我们才能保护我们在这里所做的一切。斯通纳德的兽人是我们的主要敌人。我们不寻求引起一场全面的公开战争，但被我们的敌人侦察可能会导致我们的毁灭。$B$B斯通纳德斥候已经在向东试探了，我们必须阻止他们。冒险出去，杀掉你找到的所有人。就像多年前为保卫这些城墙而牺牲的勇敢的步兵一样。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40080, '嘿，旅行者。我想找人送一个包裹，我的发货时间已经迟了。我没有履行我的义务，在坟墓里来来去去。$B$B向北，经过瓦尔甘农场和亡者农场，是一条通往提瑞斯法高地的通道。它紧靠着群山，有些隐蔽，但敏锐的眼睛应该能发现它。$B$B一旦你进入高地，我需要把这个包裹交给药剂师沃格林。他的位置应该离通往悬崖的通道很近。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40082, '在锯齿状的山顶上，厨师纳奥统治着杂毛豺狼人的联合部落。他一直相当顽强，甚至在我们过去试图对付他的时候也是如此。如果我们真的想要驱散豺狼人，让他们陷入混乱，那么我们就需要打击他们的领导核心。$B$B厨师纳奥一直是团结豺狼人的人，没有他，他们就会崩溃。当你在那里的时候，一定要杀死贝伽。他是一个萨满，强化了那里的生灵，并激励他们的行动，甚至更多。$B$B当这两个人倒下时，豺狼人们就会散开。把他们的两只爪子都给我，你就可以得到银子作为报酬。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40084, '很长一段时间以来，我一直困惑于为什么他们现在施展的魔法如此熟悉，以至于就在我的指尖上。当你与执法者及魔术师们打交道时，我更加努力地研究并得出了结论。$B$B我敢肯定，这是肯瑞托的魔力。在我的生活中，我花了相当多的时间在达拉然的法师周围，现在我回想起来，检查我的书，我很确定。$B$B如果达拉然在这里，那就意味着他们一定在试图阻止我们在提瑞斯法高地的扩张。$B$B返回盗贼高地并搜索山坡。检查肯瑞托存在的任何来源，并了结它。我们不能让我们的敌人在乡下为所欲为。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40093, '我们的姐妹船，“潮汐大师”号，在海岸附近失事，我们在珊瑚暗礁搁浅后遭受了可怕的伤亡。岩石撕裂了船，鱼人袭击了船员。没有人活着讲述这个故事。这艘船太棒了，现在它像一艘损毁的沉船一样坐沉在暗礁里，好像要让伯拉勒斯蒙羞。$B$B我们无法处理“潮汐大师”号或其遇难船员的外壳，但我们仍然需要恢复航海日志。我没有船员去冒险，特别是有鱼人和相当敌对的鱼在那里的水域。你将是那个冒险进入残骸并从它的箱子里取出航海日志的人。那里的信息不能落入我们的敌人或海盗手中。$B$B你会在西北海岸找到你要找的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40094, '一群由“水鼠”乔吉带领的海盗伏击了我们，让我们被困在岸上。我们的姐妹船的情况比我们糟糕得多，但我们仍然在这个岛上忍受了许多艰难困苦。岸上的战斗摧毁了所有三艘船。乔吉的船在岛的西侧进水后冲上了岸。$B$B他和他的人被困住了，就像我们一样，我知道他还在外面。我想让你为凯兰上将的死去取他的首级。把它带给我，我就把他出名的金耳环给你。沿着明亮的海岸查看岛屿的西侧。他和他的船员留在那里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40097, '他们的斥候走了，我们终于可以发动攻势了。但在我们策划攻击他们的主要营地之前，我们需要削弱他们监视我们行动的能力。$B$B就在耳语森林的北面，有一座名为沙特里奇的塔。遗存者的哨兵已经把那座塔作为他们的行动中心，他们在那里警告他们的主要基地任何潜在的危险。他们在沙特里奇的人数很多，这就是为什么他们不希望有一个强大的敌人直接攻击他们的原因。你能胜任这项任务吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40098, '我很高兴我对你的判断是正确的。随着迫在眉睫的危险的到来，现在是时候让你了解一下达尔索斯的房子了。在天灾蹂躏这片土地之前，我们的房子是洛丹伦最著名的房子之一。然而现在，我们分裂了，因为我的嫂子是那些仍然活着的人的统治者。$B$B这就是我们的问题所在，因为我的妻子是这片土地唯一真正的继承人。你当然有能力，这就是为什么你赢得了与格雷达公爵夫人会面的权利。沿着格伦郡南部的路走，经过提瑞斯法高地的大门，你会在路边的庄园里找到我的妻子。$B$B哦，一定要把这封信交给她。这是一个……比方说，某种推荐。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40103, '所以，不仅是部落，现在我们还得担心一些该死的邪教？呃，我必须说，我不喜欢这个，但这只是我们必须在别人之前获得车牌的另一个原因。谁知道奥丹姆隐藏着什么秘密。$B$B   $B$B如果维丝发现的是真的，那么集合的第一块应该就在这个位置。当你忙于这项任务的时候，我会准备一支装备精良的探险队去悲伤沼泽寻找第二块。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40104, '有些事情不对劲，$N。仍然没有我发出的探险队的消息。$B$B当我试图保持乐观时，我能感觉到有些不对劲。我不想问你这个问题，因为你已经做了这么多，但你是我唯一可以依靠的人。$B$B请去悲伤沼泽，看看我的人民发生了什么事。维丝为我们标记的位置指向沿着山脉的沼泽的东南部。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40105, '我从来没有求过谁，$R，但我现在没办法了。求你了！为我们报仇，让那些混蛋看看当你与联盟为敌时会发生什么！他们——<咳嗽>——从这里往北走了。$B$B为了卡兹莫…… ') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40110, '这个图腾将帮助我进入一个更深的恍惚状态，并允许我与旧的灵魂交流。在他们的帮助下，我们也许能找到你丢失的石板。$B$B$B$B噗，我都忘了这个仪式有多累了。你寻找的石板非常强大，$N。把这个信息展示给图希克，他就会明白下一步该把你送到哪里。但请注意，我们并不是唯一在寻找这些石板的人。黑暗中的某个人或某物也在追踪。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40121, '该地区鬼爪狼的首领被命名为幽灵猎手。他是一头凶猛的野兽，在该地区领导着一群狼群，意图危险。如果要实现自然的平衡，就必须杀死野兽。$B$B你应该在法拉西姆湖西北和佐拉姆斯特兰德东南的山上找到他。祝你打猎好运。幽灵追踪者是一只聪明的野兽，直到今天我都不知道。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40125, '看来我已经想不出是什么导致了这种情况。我不愿承认智力上的失败，但我必须向别人寻求答案。大法师安斯雷姆·鲁因维沃尔精通的东西比我知道的还要多。我需要你带着一箱你之前收集的魔网碎片去找他。$B$B如果有任何线索或魔法在它们身上徘徊，也许他会有一些答案，并知道他们的起源，以帮助我在艾萨拉这里。请带上这些硬币去旅行。达拉然离这里很远，我会尽我所能帮助你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40140, '随着大部分亡灵的消失，是时候面对那个负责从我们手中夺走我们新部队的人了。再次前往科林斯农庄，杀死负责的通灵师瑞吉诺德。$B$B小心。假设亡灵巫师能够召唤一小支亡灵军队。在这种情况下，他当然不是一个应该被低估的人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40141, '我来自一个大家庭，这个大家庭曾经占据了库尔提拉斯的行政区。我们不是一个富裕的家庭，但我们也不穷。当第三次战争在洛丹伦爆发时，我和我的两个兄弟一起出去旅行，希望能获得一些财富和荣誉。我帮助海军，我的兄弟卡尔开始在米奈希尔港工作，而萨穆尔去南岸协助战争。$B$B自从我几年前起航以来，我就没有和他们交流过。如果你能给他们两个送一封信，帮我联系他们就好了。他们一定以为我死了，这么长时间没有说一句话，也没有见上一面，我想让他们放心。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40142, '从我们在海上的时候起，就是我们水手想出了船上的美食。当你一遍又一遍地吃同样的饭菜时，它们会变得重复，所以是时候即兴发挥和创新了。当我们在泰拉比姆呆了几天的时候，$B$bi想出了这个食谱。我们只有沙爬虫和香蕉。把它一起炒，加一小撮盐，然后你就可以吃一顿饭了！遗憾的是，我们没有香蕉，但我知道主厨詹克尔有一些盐。从他那里得到盐，从这些岛屿周围的任何一种沙爬虫那里收集一些腿，然后我终于可以换一顿饭了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40143, '南海海盗直接威胁到我们在这个岛上的生存。他们在这里的行动比我们出发时最初预计的要大得多。他们仍然有许多强大的船只，虽然他们还没有尝试在我们的城镇前面航行，但可能性仍然是真实的。$B$B库尔提拉斯一直在与海盗作战。那些威胁商人的人是对我们王国的直接威胁。我需要你去抢来南海海盗的腰带，这是一个在广大地区活动的海盗团伙。你可以在两个大岛上找到它们，也可以在拉匹迪斯海岸西南以它们命名的沙洲上找到它们。$B$B作为你行为的证据，把他们戴的腰带拿二十条来给我。你的努力不仅会帮助我们，也会帮助所有在茫茫大海上旅行的人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40148, '哦，回到海上。。回到海上，在回家的路上。在岛上的这一部分漫步简直就是地狱。我们水手唯一拥有的就是一杯麦芽酒和彼此的陪伴。$B$B朗姆酒很好，但我们一直渴望更多的品种。这就是你要进来的地方。南海海盗以他们自己的南海珍酿配方而闻名，只有他们才能制作。如果你能偷到配方，然后我们就可以自己做了。$B$B他们目前躲藏在一片被称为南海沙洲的沙滩上，以及邻近的一小片被称为酿酒岛的沙滩上。它实际上是一个该死的工厂。他们有一支训练有素的队伍昼夜不停地工作，把这些东西抽出来。$B$B他们在西南部，在拉匹迪斯岛海岸附近。你应该看到他们的几艘船停靠在那里。发明这个配方的人名叫‘月光’玛提。你会从他那里得到的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40151, '强大的玛贡和他的儿子哈古是两个海洋巨人，他们在拉匹迪斯岛和周围的水域漫游。尤其是哈古，他在几周前袭击了卡兰之墓。虽然没有人受伤，但在海军陆战队集合并想出阻止他的计划之前，他弄到了一些重要的物品。$B$B其中之一是水滴石，一种神奇的强力石，它被强大的水术师的能量所引导。有了这块石头，我们可以更准确地储存我们的能力。我希望你能夺回它，杀死拼命的哈古，夺回这个宝贵的宝藏——不仅仅是为了我们水术师，但这样它就不会落入坏人之手。$B$B你应该在拉匹迪斯海岸的某个地方找到哈古。他最后一次出现是在西边的明亮海岸。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40152, '我们的舰队由一个高等精灵舰队中队伴随。他们和我们一起去岛上执行一项秘密任务。我在他们的船员中有很多朋友，他们是我在库提拉斯认识的。高等精灵都是好人，但他们的领袖，费隆是一个相当可疑的人物——他交易非法商品，与令人厌恶的人打交道。$B$B很遗憾地说，那些我曾经称之为好朋友的人中，有许多人现在正在吉利吉姆岛上的费隆之愚海岸出没。他们被深潮纳迦杀死，尽管费隆渴望交易的一件物品现在让他们坐立不安。$B$B去那里释放死者的灵魂。你会在拉匹迪斯南部的吉利吉姆岛的西海岸找到他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40156, '在他们领袖的激励下，戈尔多什人可能永远不会放过我们。暴君之王是一个相当令人生畏的野兽，他领导了食人魔在这里的第一次进攻。他很固执，甚至不听他的萨满或他最聪明的预言家的建议。$B$B如果我们要真正阻止高多什，这个暴君必须被铲除和杀死。你会在戈尔多什高地找到他，很可能在他们最大的营地里。冒险前进，确保他不会再给我们带来麻烦。把他头上戴的弯曲的王冠拿来给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40158, '欢迎来到哈祖里林间空地。只要你保持和平，我们欢迎你来这里。我们靠自己找到了自己，我在寻找古老的配方和力量。在遥远的卡利姆多大陆上，有一个叫做艾萨拉的地方。这个地方拥有许多秘密和巨大的能量，我希望在哈祖这里利用它们。$B$bin在这个地方，有一种名叫“电角蜥蜴”的角鹰兽。从他们那里，我想要一个原始的雷头号角。这只号角将极大地帮助我和原始人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40162, '你好！我的名字是斯莫吉尔，我曾经是鱼人的一部分，直到我们来到这里，他们加入了滑溜溜的纳加！他们现在叫深潮，攻击任何靠近的人，他们甚至偷了我的项链！$B$B那些是我的，是我做的，是我给朋友的，他们把它们都偷走了。我试着友好地请求，但他们伤害了我，我想让他们回来。你能把我的项链拿回来吗？我不需要全部，只需要几个，也许六个。我知道这里的其他鱼人也有，所以，你一定要好好问。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40163, '拉皮迪斯之塔笼罩着我们，就像一个巨大的恶魔，随时都可能摧毁我们。当我们第一次到达这个岛时，大水术师拉匹迪斯在我们的一些工人和他自己的元素的帮助下开始建造一座塔。水的全部。凭借他强大的力量，这座塔早在凯兰镇的安息之地站稳脚跟之前就建成了。$B$B凭借他的力量，他与祖尔哈祖的巨魔和戈多什高地的食人魔结成了联盟。从那时起，他就一直和我们作对，自从塔建好后，他就再也没有和我们说过话。一直被强大的水元素守护着，并被一扇魔法之门封印着。$B$B如果我们还有希望，那么必须杀死大水术师拉匹迪斯。弗雷克利夫是一名水疗师，在拉皮迪斯手下工作，如果有人知道从哪里开始，那就是他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40164, '大水术师拉匹迪斯拥有令人难以置信的水术师技能，甚至比伯拉勒斯上的许多人都要强得多。许多人对这个人如何能够获得这样的权力有自己的看法，但我总是对他持怀疑态度。我相信他得到了魔法神器或外力的帮助。$B$B无论如何，如果有办法进塔，我相信办法就是这把钥匙。<水术师弗雷克利夫拿出了一把闪亮黄铜钥匙>。$B$B这把钥匙是拉匹迪斯在我们到达之前交给我的，他把它托付给我保管，我是他的学生之一，但之后他建造了这座巨大的塔，并将自己一个人关了起来不见其他人，我就回到了这里。这把钥匙可以打开塔的锁，但不能打开大门，也许还需要一些魔法调谐。$B$B我们必须向那些对奥秘有更多了解的人寻求帮助，达拉然的大法师大法师安斯雷姆·鲁因维沃尔也许可以帮助我们，找到他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40167, '随着钥匙被施了魔法，拼图的一部分已经就位。然而，我不具备能够给这把钥匙一个创造它的人的调谐的技能。一旦调谐到这把钥匙的力量是令人难以置信的强大和复杂，需要比我更有技巧的人来做这件事。你可以把钥匙还给水钻弗雷克利夫，也许他知道另一个。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40170, '。$B$bi可以做到这一点，虽然我一定想知道为什么我会帮助你，尤其是免费的。$B$B如果你想让我施展这把钥匙的魔力，并为你调整它，我需要你的帮助。我很久以前就认识一位萨提尔，他至今仍在这个世界上行走。让我们说，我和他的立场不是最好的，我想让你从他被殴打的尸体上给我带来他的一只粗糙的角。$B$B前往费尔伍德，前往星座废墟，你会在那里找到破萨斯·黑角，我想要的是他的角。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40172, '喂，伙计，天气真好，不是吗？$B$B<加菲尔德深吸一口气。>$B$B啊，海水的咸味强烈地进入你的鼻孔，昨晚朗姆酒残留在嘴里的味道和你在当地酒吧打架时的宿醉和疼痛。在这没有更好的生活了伙计，这个城市很无聊。我认为他们不是真正的海盗。如果你真的想在海上冒险，看看海盗船到底是什么样子，你应该加入我和我的船员！$B$B我是血帆海盗队的一名船员，我正在寻找新的人加入我们。我们是藏宝海湾的死敌，所以考虑一下呗，嗯？如果你决定加入我们，我有一个任务给你，如果不是，我们从来没有见过，懂？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40174, '好的伙计。到目前为止，你做得很好，但在离开这个烂港口之前，我们还有一些事情要做。如果我们想让这些白痴在面对血帆海盗时永远没有机会，我们也必须对他们的弹药做手脚。他说，我要给你一瓶“特殊”的水，你必须把你能找到的任何一桶炸药都倒进去。$B$B了解了？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40177, '该死，我们是不是像流星一样坠落，所有的控制装置都失控了，火花四溅，飞艇拖着屁股撞上了小岛！我能活下来是个奇迹，但当我不得不离开残骸时，我就走了背字。$B$B在我们坠落后，我们吸引了一群蛇怪的注意。那些该死的家伙让我无法去找我的弗朗兹旺格曲柄！我很久以前在科赞做了这个东西来帮助稳定，让我告诉你这是革命性的！$B$B你认为你能在飞艇上快速倾斜转弯吗？除非你有弗朗兹旺格曲柄……听着，伙计，你看我的眼神就像我是外星人一样，你只需要知道这东西很值钱，好吗？我愿意付钱让你去拿，现在我说的是你的语言吗？$B$B沉船在西南方向的莫尔奥格哨所附近，应该不容易错过！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40180, '伙计，把摩根的头放进这个海盗旗里。你不会喜欢你接下来要做的事，但那只能证明你是多么的疯狂和勇敢。你要把头扔到男爵和大副的脚上，然后跑掉！你会在哈圭罗岛上找到我们的，我希望你能活着回来，你会是船员们的宝贵财富。如果你来了，我会正式任命你为船员。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40186, '你要为我做的最后一件事是把这些傻瓜的船放火烧了。很有趣，不是吗？$B$B耶，我想让你在靠近大炮的时候点燃这个火炬，然后引爆炸药。一定要尽快离开那里！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40188, '那艘该死的齐柏林飞艇在我们经过这个未知的岛屿时着火了，幸运的是我们没有撞上公海！我们失去了很多船员，但我知道布拉兹诺在坠机前跳下了飞机。我不确定他发生了什么事，但我希望你能以某种方式找到答案。$B$B布拉兹诺是个狡猾的人，毫无疑问，他能够从我们其他人那里想出一些办法。如果有的话，我打赌他在坠机地点附近的某个地方，看看那里——你会在莫尔奥格哨所附近找到我们的残骸。就在这里的西南方，靠近峡谷。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40196, '我们的人民已经很久没有见过卡利姆多的沙漠了。我们为了财富离开了我们的部落，而现在，带领我们来到这里的人为了他自己的利益背叛了我们。我们努力奋斗获得的财富被夺走了，我们只能任其腐烂。$B$B他是一个名叫莱库格斯的半人马，他和南海海盗一起策划了这场背叛。我对他有所怀疑，但我没想到他的名誉这么不值钱。这里的每个人都想复仇，但我们没有办法杀死他。我不想说这样一条毒蛇的好话，但他凶残狡诈，武艺高强。$B$B他因残暴而被称为“掠夺者”，你不应该小瞧他。找到他，杀了他，为了我们所有人，也为了他的背叛。我不知道他在哪里，但他仍然是一个彻头彻尾的海盗，所以他应该和南海海盗们混在一起。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40197, '多年来，我们的邻居是一个熊怪，在过去的几年里，他变老了，但他非常聪明。老灰爪经常独来独往，关心自己的事情，如果他需要陪伴，他经常会冒险过来进行夜间谈话。$B$最近我担心他的精神健康，森林里的其他熊怪已经开始做出不理智的行为，我担心灰爪也会遭遇类似的命运。他已经几个月没来了，一直呆在北边的家里。$B$B他对我或阿丁都很有攻击性，我想要和他谈谈，但也许你可以先和他谈谈。问他是否还好。知道一位老朋友很好，我一定会放心的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40200, '当我们与拉泽瑞战斗时，我们能够对祖拉扎尔造成相当大的破坏，甚至占领了城市的一部分。直到一大群爬行者进来，领头的是一只叫「苔藓」的巨兽，它把我们赶了出去。$B$B「苔藓」是一只潜伏的、可怕的野兽，它在祖尔拉泽的废墟上巡逻，并杀死了许多食人魔。在故事和谣言中，我们总是认为他是一头野兽，徘徊在阴影中，让那些独自旅行的人消失。当我说我更喜欢「苔藓」的故事只是一个故事时，我想我代表了我们中的许多人。$B$B前往西边的祖尔拉泽废墟，杀死「苔藓」，把它肮脏的心带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40201, '我花了很多时间和石爪山脉上的饲养员在一起。那是一段宁静的时光，去寻找自我的真正平衡和与自然的和谐。在那里的日子里，我学到了很多如何最好地运用土地的力量来保护自然的方法。只有当我在泰达希尔开始我的工作时，我的努力才开始动摇。事情变得更……复杂了。$B$B似乎土地本身就有一些我无法理解的污染。我一直在努力改变自然的意志，使自己比以往任何时候都更加紧张。我的保护者中有一位已经枯萎，与我断绝了关系。$B$B我请您与特萨拉·白羽交谈，她曾经领导该地区的鹰身女妖。问她有没有树人的消息。不要担心；她摆脱了控制她同类的邪恶。$B$B你应该在山下北边找到她。沿着这条路走，你会在悬崖边看到她。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40204, '问候，$C。高级哨兵阿迪那·木叶给我的任务是侦察和招募有能力的冒险者来解决一些更令人担心的事件。欣泰达希尔。那些适合并且愿意的人，我将直接向她寻求进一步的命令。$B$B你会在达纳苏斯城门上的这条小路上找到高级哨兵，监视着我们的边界。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40205, '泰达希尔的瘤背部落已经成为一个比我想象的更大的威胁想想看，他们曾经是我们的盟友，对抗所有危害森林的人。$B$B月亮女祭司阿玛拉在达纳苏斯和多拉纳尔之间的道路上巡逻。保护旅行者的安全，并征募他们的援助，以抵御村庄附近的格纳尔派恩人的攻击。可惜的是，这些措施似乎还不足以削弱熊怪的进攻能力。$B$B如果我们要阻止任何针对多拉纳尔和暗影峡谷的动员，我们必须打击部落的核心。现在有理由担心他们变得有多大胆。前往南方的格纳派恩，杀死尽可能多的复仇者和追踪者。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40206, '沼泽地里到处都是昆虫、真菌和捕食者。只有其中的一小部分可以在用餐时享用。沼泽深处有一种特殊的蘑菇，是我过去测试过的。它可以被用作一种毒药，尽管小剂量的它可以在饭菜中添加很多东西，或者如果准备得当，其毒性的不良影响是可以消除的。$B$B销魂苔藓菇遍布整个沼泽地，最常见的是在浓密的树冠下或沿着蜿蜒的河流。但并不总是如此。走进悲伤沼泽，给我收集10个销魂苔藓菇，我希望能更多地接触真菌。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40213, '这条项链让我恢复了很多以前的力量。如果你在旅途中注意的话，你就会发现我的真实身份。现在你真正知道我是谁了，我们将朝着我的最终目标努力。$B$BI能够引导我的能量并找到腐败的源头。虽然我们可以很好地面对，并用我的项链的力量召唤它给我们，我首先要报复那些抛弃了对我的崇拜的人。$B$b祖尔哈祖曾经是一个我称之为家的地方，正是在那里，巨魔们称我为神。他们练习我的魔法，跟随我到世界的尽头。$B$B前往西北部的祖尔哈祖，杀死首领黑暗大师哈扎吉、冠军拉加齐和酋长沃赫佐。人们也应该受苦，从他们那里得到10个哈祖里护身符，它们将是很好的装饰品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40217, '毛尔奥格人曾经统治着岛上的大部分地区，但时代已经改变了，我们现在正在努力保持自己的完整。我们的另一个行动地点叫做莫尔奥格哨所，由烬腹领导，他是一个相当强大的食人魔。$B$B在内心深处，我仍然认为他还活着，我想让你去看看他，他坚持要留下来，甚至当我们因为蛇怪的问题而离开的时候。$B$B去看看他是否在那里，至少有他的踪迹。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40218, '在莫尔奥格下面有一个充满蛇怪的洞穴系统，叫做深颈湾，它的入口就在东北方向的海滩上。我在睡梦中做了很长时间的噩梦，梦见一种神奇的力量，好像有什么东西在呼唤我。一只有着玻璃眼睛和力量头脑的蛇怪，我以前就认出了它可怕的外表。$B$Bit是我现在搜索的魔法，并且你获得的出价。一只名叫玻璃眼的野兽的神奇凝视是我梦想的原因，而能量渗透在莫尔奥格下面。去洞穴里杀死野兽，收集它的眼睛，把它带给我。也许它神奇的力量会带给我一些对未来的凝视。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40219, '我们莫尔奥格曾经拥有许多巨大的财富，我们正在建立一个巨大的翡翠矿井，它就在吉利吉姆上！那些肮脏的海盗来了，偷走了我们所有的辛勤劳动，应该被粉碎！那些丰富的玉器是我们的，他们制造的黄金也应该是我们的黄金！$B$在我们第一次挖掘的时候，我们发现了一个非常大的“星光翡翠”，当然，在混乱中，我没能带上它！现在一个叫黑骷髅的工头拿走了，我想要回来！他沿着西北海岸去翡翠矿井，去那里，杀了他，把我的战利品带回来。也许他们也会从中吸取教训。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40224, '一如既往地干得好，我想我可以指望你出一批货。这应该藏在地毯下面，所以我不想让任何人知道是我派你来的或者他得到了什么，明白吗？！$B$BA我的好友伊格·熔油最近离开了风险投资公司。在一些不太好的条件下，我们很久以前见过面，他是个很好的走私者。无论如何-我需要这个板条箱交付给他，它包含了一些你掠夺的战利品，作为对信息的感谢，以及他所要求的。$B$B所以，朋友，就这么简单，去和他谈谈，把这个板条箱给他。你会在棘齿城找到他，就在离城镇不远的路上，他和一些朋友在那里共用一个金属加工之类的地方。在战利品海湾的码头上搭船。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40225, '虽然我很感激这次送货，但我知道这意味着什么。我很久以前就承诺过要遵守协议。我希望他掠夺我给他的地区，以换取一些货物和信息。$B$B他正在寻找杀害杰德的凶手，就是前一段时间拆散我们老船员的那个人，现在他已经完成了他的使命，我也会这么做。我不是老鼠，我守信用。$B$B组织这次袭击来拆散我们的人名叫沃利·怀斯克拉克，他现在和那些辛迪加男孩混在一起，虽然我相信\'滑\'知道这一点。一旦你告诉“斯利普”这就是幕后黑手，他无疑会想要报复。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40226, '这个人在打倒我的船员后仍继续交易和欺骗了我，我们面对面交谈了很多次。他杀了杰德，把她从我的生活中带走，我们本可以和我们的船员一起征服世界。我可能不会住在泰拉比姆的宫殿里但我仍然会得到我一直渴望的甜蜜的正义。$B$B‘俏皮话’维利是一个人类呆子，他住在斯坦恩布莱德，与那些辛迪加成员关系密切。是啊，那些把自己的灵魂出卖给兽人的叛国者，看起來背叛似乎就在他们的血液里，对吧?$B$B在斯坦恩布莱德找到他，杀了他，把他的超大耳环带给我作为证据。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40230, '法拉希姆湖是我度过大部分青春时光的地方，它是一个放松和美好时光的地方。只是现在它被盐沫鱼人接管了，他们凶残地攻击，毫无悔意。一些人在袭击中死亡，但我幸运地逃脱了。$B$B当我要离开的时候，我留下了一件对我来说最有价值的东西。我的叔叔在海加尔战役中牺牲了，他留给我一本书。这是一本关于他在战斗中的技巧和他关于战争的经历的书。我从那本书中发现了很多知识和智慧，我想知道他在去世前记下的一切。$B$B前往西南方向的法拉希姆湖，找到我的书。当你在那里的时候，一定要为我们报仇，杀死盐沫鱼人，把它们的鳞片带回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40235, '我，威廉，是个言而无信的矮子，我将信守诺言，揭开我们面前这片新疆域的面纱。我们首先要去的地方是科林渡口，这是一个被天灾占领的地方，而不是我要去的地方！$B$ba一本名为《黑暗锻造的秘密》的书可能是揭示我们所寻找的东西的第一步，它由雅各布·马尔赖特持有。他在活着的时候是一个相当有名的铁匠，现在却在死人中行走。毫无疑问，他还带着它，或者把它留在身边，杀了他，把书给我，让我们开始学习他们的把戏！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40236, '“工匠威廉会花时间通读这本书，阴谋标记他的特征，兴趣点燃他的眼睛”。$B$B这本书包含了很多信息，我的意思是，其中大部分似乎与我们正在做的事情无关。为什么我们一开始就想要黑暗的束缚呢？!$B$B有几个部分可能与此有关，其中一个部分被黑魔法污染和扭曲，使其无法理解，坦率地说，令人不安。另一部分似乎是由一个名叫洛提拉斯的恐惧魔王写的，他可能会有一些用处。$B$bi首先想揭开黑魔法的面纱，我相信我认识的人可能会有所帮助！斯坦哈德·法尔杉曾经是我的一个朋友——我们的关系不是很好，但他与暗影魔法和恶魔都有很深的关系。$B$B他位于棘轮，去那里找到他，把书带给他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40237, '你在这里处理的事情很有趣，这本书似乎提到了很多关于黑暗锻造的模式，你很少会用到它。亡灵使用的盔甲和武器与让他们的爪牙屹立不倒的魔法深深地交织在一起。$B$B如果你需要我的帮助，那么我也会需要你的帮助，我可以发现这段文字的内容，并为你和威廉指出正确的方向。但这需要帮忙。$B$B前往通灵学院，深入其中。我在里面找一本前一段时间在那里存档的旧书，书名是《火的召唤和命令》。$B$B把这本书给我，我就照你说的做。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40239, '我在破影峡谷的时间是一段思考和研究的时间。我渴望了解艾泽拉斯各个派别的魔法领域，看看他们已经走了多远。$B$虽然我可以渗透，并花费精力通过时间、播种种子和混乱来进入每一个地方，但我更愿意招募你，为我这样做。如果你真的想获得知识来调和这把符文之刃，我会暂时授予你。$B$B首先，前往上黑石塔，从狂爪火舌龙人身上，为我收集一个狂怒魔爪符咒，其次，前往厄运之槌，从食人魔法师领主那里给我一套戈多克念珠。最后，从黑石深渊的矿坑中，从末日之炉魔匠那里收集他们的末日之炉法杖。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40242, '你好，欢迎来到亚麻须前线新人！我是艮泽尔·扳晕，负责启动新项目并记录旧项目的成功和失败。$B$bi有一个可能可行的新想法，一个带电荷的外壳既可以作为盾牌，也可以作为屏障，既可以保护又可以抵抗魔法！当然，我们首先需要一些贝壳，我们没有一堆金属可以浪费，但周围有海龟！$B$B出去，给我收集3个原始的潜伏者贝壳！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40250, '正如你所看到的，在这些被遗弃的土地上几乎没有生物。尽管如此，你的下一个任务是将天灾瘟疫的另一个受害者置于你的控制之下。然而，不死宠物不是那么容易被征服的。$B$B洛丹伦曾经能看到棕熊在夏天从银松森林迁徙，躲在我们的森林里，吃掉农民的庄稼。那些在瘟疫期间被留下来的人现在永远在这里。像你一样打破了生死轮回，他们迷失了，困惑了，怨恨了。$B$B随着你技能增长，你的野兽也在变强。对于不再有生命的生物，这将需要极大的耐心和奉献精神，深入到他们任性的头脑中，找到挥之不去的智慧火花。只有这样你才能训练它。$B$B熊是一个坚强的伙伴，它会站在你和伤害之间。凶猛地阻止你的敌人，这样你就可以在他们站着的地方射杀他们。找到一只瘟疫熊，唤醒它的思想，把它带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40253, '欢迎来到我的寒舍，我在这个塔尖上履行了我的职责，并将继续这样做。现在路石已经重建，我们可以开始让我们在该地区的存在更加广为人知。$B$B西南方向是辛玛洛神殿，坐落在埃达拉斯废墟中，目前居住着扭曲的纳迦。在辛玛洛神殿里，隐藏着他们永远不会发现的秘密，而我需要你去揭开。$B$B在神殿深处，你会发现一块独特的石头，上面刻着一种更古老语言的明亮符文。这块石头，被称为阿山石，当你看到它时，说出下面的“TizahAshanDal\'Asha”。这个魔法将再一次削弱延伸穿过艾萨拉的长而不活跃的魔网线。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40254, '我们下一步的行动需要我们更加大胆。如果我们要解除失落之城许多埋藏的秘密，那么我们必须收集大量的莱伊能量来引导。在厄运之槌的深处，我的上层精灵亲属一直在使用大量的奥术力量。据我所知，这种神秘的力量控制着一个邪恶的存在。我相信他们正在利用这个存在来满足他们可能被消耗的任何魔法上瘾。$B$B冒险进入厄运之槌的深处，杀死这个被囚禁的生物，它应该拥有纯净的莱伊精华。我们可以用它来引导咒语进入被掩埋的城市。$B$B随着亚山石的激活，我们将需要快速，所以不要浪费时间。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40255, '不久前，一队士兵出发前往悲伤沼泽。他们的任务是开垦沼泽地西部边缘山脉中的一座旧城堡。守望圣骑加纳苏斯是这群人的首领，他让我为他和他的手下祝福。$B$B毫无疑问，他们将需要帮助，也许一双新的手可能会受到欢迎。悲伤卫士要塞应该就在逆风小径的入口附近，事实上它就在那里。信不信由你，它曾经被用来保护王国的边界。$B$B如果您看到加纳苏斯，请告诉他我向他问好！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40256, '黑石氏族属于古老的部落，是奥格瑞玛的一个巨大而危险的敌人。不要被黑石山和奥格瑞玛之间的距离所迷惑。如果黑石氏族获得了相当大的力量，他们也会来摧毁我们。旧部落由许多派系组成，这些派系在第一次和第二次战争期间留在东部王国，是一个灰色地带。不应被低估的敌人。$B$B我从奥格瑞玛被派到这里，受命袭扰黑石氏族，你会帮忙的。这毕竟关系到部落的荣誉。$B$B为我收集20个黑石印记，由该地区所有黑石氏族成员佩戴。杀了他们，拿走他们的图章，把他们带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40260, '啊，你是一个很有前途的猎人，但恐怕我已经没有什么可以教你的了。既然你一直在为被遗忘者和我们的女王服务，我想是时候让你去布里尔了。$B$B在你完成这里的所有任务后，寻找黑暗游侠拉里萨，她将在布里尔镇的一个帐篷里。$B$B她会教你任何你需要知道的东西来继续你的任务，这些黑暗游侠是和我们的希尔瓦娜斯女士一起从奎尔萨拉斯带来的。根据他们的名字，他们在枪法方面非常熟练。$B$B永别了，记住要坚守阴影，为了被遗忘者。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40261, '你好，黑暗游侠追求者。你似乎完全有能力控制一头自称属于你的野兽。虽然我可以教导你以猎人的方式，但我不能教你如何驾驭野兽。$B$B您必须与布里尔的利奥特·鬃皮通话。只有他拥有你所寻求的知识，才能征服这片不幸土地上的生物。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40263, '黑暗游侠，兰尼萨，建议我在你完成训练后，专门找你来完成一项任务。她和我都同意，这将是你的技能和对被遗忘者事业的奉献精神的适当展示。$B$B即使在瘟疫来袭之前，我们的现任市长仍然主持着布里尔。博尔特鲁斯是市长的助理，一个安静而能干的人。他对周围农场的一个女孩很有好感，有传言说有一个秘密约会。$B$巴拉斯，被瘟疫所触动，超越了黑暗女士的救赎，博尔特鲁斯作为天灾恶魔困扰着提瑞斯法。市长要求结束他的痛苦。你可以在巴尔尼尔农庄的谷仓里找到他。也许他还记得和她在谷仓里度过的那些夜晚。$B$B找到保尔楚斯，结束他的痛苦，并将他的遗体带回给黑暗游侠拉里萨。也许那样他就能找到平静。你的仁慈会得到回报的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40264, '大家好，欢迎来到莫尔奥格避难所，我们是一个饱受摧残的民族，一直在为统治地位而战。我是哈兹戈尔格，我是先知的首领。$B$我早就看到了我的人民的毁灭，在漫长的狂热的梦中和黄昏的黑暗时刻里的幻象中被预言。我担心，我们被吞没的持续战争状态只会导致我们的终结。$B$bi请你代表我和克鲁克佐格勋爵谈谈，告诉他我相信这种鲁莽的攻击只会带来痛苦。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40266, '我看到了很多东西，巨大的黑暗不仅笼罩着这个岛，也笼罩着我们周围的一切。我的人民听从了更强大力量的命令，心甘情愿地跟随它进入黑暗。在我们灭亡之前，我们只不过是棋子。然而，$B$B我确实看到了比痛苦更多的东西，我看到了高多什食人魔的预言家，他是我曾经的老朋友。也许是他可以提供一些智慧，或建议如何继续下去，也许是他，谁有答案。$B$B伯乌克先知在戈尔多什高地和他部落的其他成员住在一起，你应该在遥远的北方的拉匹迪斯岛上找到他。戈尔多什高地位于其西北侧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40270, '我在阿塔尔哈卡神庙里有过很多次邂逅，很长一段时间都在凝视它的墙壁。这是一个充满黑暗和邪恶能量的地方，它曾经的捍卫者已经堕落了。先知贾玛兰对他的人民的腐朽遗迹说出了他的污秽、拙劣的话，他们称这个地方为家。我希望你冒险进入这个地方的地下墓穴，找到先知，并从他那里收集阿塔尔艾棒。它应该被保存在靠近这个巨魔传递魔法的地方。$B$b阿塔尔艾棒在控制魔法中拥有力量，应该可以帮助我们征服克鲁克佐格领主。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40274, '当我们第一次在这里定居时，怒水河并不总是那么糟糕。洪水和汹涌的波涛考验着我们的意志，考验着我们新家园的自然力量。但最近发生了一些变化，导致鳄鱼数量大幅增加。$B$B我想做的是整天钓鱼，但现在我不得不击退野兽，花更多的时间用手中的武器，而不是在我的钓鱼点享受。$B$B在你问之前，我已经为一生做了足够多的战斗，从敦霍尔德之围到圣山海加尔。我只是想放松一下，并以这种方式做出贡献。出去保护我的钓鱼点，我会给你一根我手工制作的鱼竿。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40276, '你做得很好，你拥有最全面的探险家的坚韧和力量。如果我们真的想让深潮消失，并让这些岛屿摆脱它们的存在，我们必须变得更加大胆。他们的领导是依偎在深潮密室，需要被根除。$B$返回密室，并对莎扎公主和海潮之王哈凯仕进行报复，他们需要为他们的罪行和敌意而被杀死。相信我，没有理由，也没有外交手段，完成这件事，也许纳迦就会散去。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40278, '$R，我有个任务给你。一个相当重要的任务。$B$B<纳格拉斯向您展示一个装饰精美的珠宝盒>。$B$B这里是提瑞斯法高地的地契。你看，在天灾入侵之前，我的妻子格莱尔达应该从她父亲那里继承这些土地。在加冕典礼那天，这个盒子里的东西应该传给她。$B$B许多个月过去了，但我和我的朝臣们都没有运气打开这东西的锁。但在我研究的过程中，一个名字出现了。瓦瑟拉斯·米尔森。他专门研究这类事情。去陡崖港找他。我听说他现在开了一家客栈。$B$B哦，一定要小心。这个盒子比你的命还值钱。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40288, '现在，还有最后一步，刀刃要重新锻打。$B$B咱要搞个强大的传送通道，一个巨牛逼的魔网能量源来把刀片拼回去。这就是剑圣之道。冒险前往恶魔仍然潜伏的费伍德森林。收集他们的恶魔能量，然后回到我这里，这样我们就可以重新铸造这把剑了。$B$B加德纳尔的恶魔避难所将是一个拥有这种能量的地方，瞧那，命运女神保佑咱，那破洞可不好进，小心别死里面。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40289, '最后一件事，俺求你拜拜死人，你帮俺好多，所以俺请你替俺拜拜咱死掉的朋友。俺把这剑用心修好，要好久才能搞的和新的一样。$B$B来咱一起，念出死掉朋友的名字，这样他的灵魂就可以和他战士老伙计一起了。你也能把他的勇士精神传递下去。$B$B他叫\'塔克加·深仇\'。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40292, '万岁，$C，你感觉到了吗？魔法，在我们周围噼啪作响，永远强大，即使在数千年后。这个地方曾经是辛—艾萨莉，暗夜精灵帝国的首都。$B$B现在，它只不过是一片荒地，被纳迦甚至更邪恶的势力占领。然而，我有一个幻象，巨大的骚乱来到这个地方，如果我们不阻止它，后果将是……可怕的。$B$B不幸的是，我的视线不清晰，笼罩在迷雾中。我需要进入萨满的冥想状态才能看清楚。然而，我缺乏进入这种状态的适当成分。我本应亲自收集它们，但我现在不能离开前哨基地。我不需要太多，只需要苔蹄鹿角来粉碎，还有一打上层精灵的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40297, '蓝龙军团自远古以来就一直在艾萨拉，但他们最近的行动似乎很奇怪。他们在那里保护古代文物，而不是耗尽生命和魔法的能量。在更好、更简单的时候，我会建议你联系他们，并尝试谈判。$B$B那些时代已经过去了，我们需要采取行动。回到艾萨拉，召集一支强大的队伍。冒险去梅纳湖，杀死他们的亲人。这将减少他们的人数，我们将有时间准备对他们的行动作出更好的反应。$B$ba不幸的是，龙族已经开始扰乱艾萨拉的自然魔法。完成后，返回血拳点的亚格奥仕。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40298, '双足飞龙原产于卡利姆多，在我们的大部分土地上都可以找到。事实证明，它们是我们风骑士的忠实伙伴。我记得我们第一次确保这些美丽生物的帮助的日子。$B$B说实话，它们是大地母亲的礼物，加强了兽人和我的人民之间的联系。可以毫不夸张地说，没有他们，就没有我们今天的成就。$B$B刺毛在这里已经被驯服了。她不会攻击你的，放心。$B$B事实上，自从我忘了把她最喜欢的玩具带到杜隆塔尔后，这个可怜的女孩似乎有点无聊。如果你有时间，年轻的$C，请给她找一个新玩具和一些零食。作为回报，我相信她会很乐意带你去天空一小会儿。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40300, '向年轻的$C致敬。你是不是注定要去人类的暴风城？如果是这样，我想请你帮个忙。$B$B在我的亲戚中，钓鱼是一种罕见的职业选择，但我却从中获得了很多乐趣。真的没有比这更轻松的方式来打发时间了，这是我们卡多雷不缺的东西。我经常从我钓鱼的岸边收集蛤蜊，里面有珍珠，就像艾露恩在最黑暗的夜晚一样洁白。$B$B它来自这些珍珠，我为莎莉恩制作了一条项链，她是我几十年来一直渴望和追求的女人。请把这条项链交给她，并告诉她这是她的秘密仰慕者送的。让我迅速地用一块布把这个包起来。$B$B到达暴风城最快的方式是从奥伯丁的南码头出发。一旦到了暴风城，你应该能找到住在花园区里的莎莉恩。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40433, '守望堡是一个与世隔绝、相当荒凉的地方。我们需要一支强大的，足以抵挡住恶魔入侵的强大力量。$B$B我麾下的士兵有家园和家人，士气在这里至关重要的。我依靠我的中士给我一份关于我手下人员状况的情况报告。$B$B到目前为止，我唯一等待的是伯恩赛德中士，你能帮我一个忙，你能不能帮我去他那里取一下报告？你可以在门外的某个地方找到他，他可能和他的部队在一起。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40458, '好吧，$G小伙子:小姑娘;，监视报告刚刚传来。看来老兄弟不再孤单地在外面了。根据情报，根据情报，在大山的另一边，有一个疑似采石场的地方，暗炉矮人正建立一些东西。至于他们挖的是什么，那就是一个迷了，因为没有人进去过，除非是和他们一起进去的，否则永远不会活着出来。$B$B这就需要你了。召集你的朋友，或者雇佣一些佣兵，进入采石场内，看看他们到底在挖什么。现在就去！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40576, '<高兴地哼哼。>$B$B一场盛宴！碎牙的盛宴！现在谈谈那个<哼了一声。> 石板。这封信本来是要<哼了一声。>送达克劳尔首领那里的，因为他们报告说，野猪人确实<哼了一声。>想要袭击旅店，但当他们到达旅店时，旅店已经<哼了一声。>被烧毁了！$B$B不确定他们说的是哪个<哼了一声。>旅店<哼了一声。>，但看起来你是知道的。$B$B碎牙很高兴<哼了一声。>帮忙，牛头人对碎牙真的很好。$B$B即使这个笼子也是<斯诺特。.> 现在是敞开的，但我选择<哼哼。> 留下来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40686, '我来拜访我的好朋友德罗恩，庆祝我家乡的啤酒节庆祝活动，并创造一种新的啤酒。$B$B德罗恩收集了一些异国情调的原料，可以制作出一种非常有趣和有效的啤酒。也许您也有兴趣帮助我，是吗？作为回报，我会与您分享我最新的惊喜啤酒。$B$B为我获取以下内容：一小撮魔尘、十四个蛇麻草和一些金棘茶。这些原料可以在世界各地找到，因此您可以前往异国他乡和市场。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40723, '我们已经在这些沼泽中尽了自己的职责，现在我们应该与联盟一起解决问题。把这个勋章交给法尔格兰·哈斯蒂尔，他是与卡古隆会面的侦察兵。$B$B他可以把这个令牌带回给他们的领导人，让他们知道我们的援助。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40799, '他们还没有回复我！我的兄弟姐妹怎么看起来这么简单？多么令人气愤！$B$B<当她未能将其中一只雏鸟召唤到她身边时，她的耳朵会竖起，她会露出獠牙。>$B$B 我的山多会告诉我放下我的骄傲，我\' 我确定。他的方式始终是耐心的。我恳求你，$N，去找角鹰兽大师并请求他们对这些任性的孩子提出建议。不遗漏我的挣扎细节，尽管承认我需要他们的帮助让我很痛苦。$B$B等等！不要与卡里拉斯或菲尔德伦说话！我不能接受只能被视为优惠待遇的东西。$B$B 我强烈建议你前往鲁瑟兰村和阿斯特兰纳，我相信我曾经收到过来自奈杰尔角的信件，无论那是在哪里。石爪峰上的特洛伦我确信他会在这方面帮助我，但要注意他的……漫无目的的倾向。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40824, '<克罗格发出一声低沉、隆隆的笑声。>你觉得我们在监视塞拉摩怎么样？哈！好像我们会把时间浪费在那些弱者身上。不，不，我的朋友。我们碰巧拥有了他们的账本，这只是一个巧合。他们似乎把它们丢在沼泽的某个地方了。我们很幸运，嗯？$B$B<克罗格翻开账本，用粗大的绿色手指在页面上划过。>$B$B让我们看看这里……啊，是的。V—A—N—D—O—L。大约四年前，他乘船来到塞拉摩，然后乘坐一艘小船沿着海岸线向南航行。恐怕这就是我们要做的一切。$B$B现在，如果你真的很想找到他，我想你可以尝试从走私者那里租一艘船，然后沿着海岸航行。不过要小心。有传言称，一名复仇心切的水手最近一直在海岸上制造恐怖事件。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40856, '诺莫瑞根错综复杂的管道、管道、渠道、通风口和气道网络对于维持健康的空气流动至关重要。然而，它们也散发出有毒气体，对我们的弟兄造成了毁灭性的影响。$B$B 作为预防措施，我们建立了一个全面的备用系统，可以在紧急情况下重新引导气流。不幸的是，其中许多通道已被关闭和密封，需要操纵杠杆和阀门才能重新激活它们。$B$B我们需要您的技术专业知识才能进入城市内的两个关键接入点。第一个是阿尔法通道，它负责我们的备用发电，位于工程实验室内。第二个是备用泵通道，位于发射台附近，这对于我们备用空气泵的运行至关重要。$B$B这些通道必须激活！我们必须让伟大的诺莫瑞根城恢复昔日的科技奇迹！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40994, '我已经目睹了真相，仿佛亲眼见证了寂静守卫教堂的第一次战役。那些古老的卷轴记载了加拉隆·格雷迈恩娴熟的战术，如今却被揭示为一幅谎言的织锦。他驾驭着一股不祥的力量，源自于连我的思维都难以理解的存在。他手中紧握着一柄权杖，通过它他能够操控黑暗的本质。其无比的强大简直令人闻风丧胆。$B$B我们不能让这股力量落入敌人之手。如果他们揭开真相，可能会给我们的事业带来厄运。请仔细听好。在我视野的深处，我认出了那柄权杖的样貌。它曾经就在拉文伍德城堡的大厅之中。$B$B然而，现在拉文伍德城堡已经成为废墟，被格雷迈恩的军队所摧毁。我们只能祈祷那柄权杖没有被他们夺走。$B$B前往拉文伍德城堡，寻找一只由黑曜石铸造的节杖，并把它带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41003, '你需要卡拉赞之怒吗？嗯，这些并不会随意赠送给公众成员和塔楼的客人。它们是通过向麦迪文慷慨捐赠和他所提供的魔法服务而获得的。如果你想要一枚卡拉赞之怒，我们可以代表你进行捐赠，以便在我们的主人回来时使用。目前，我们正在寻找10个死灵精华、10颗生命精华和25枚金币作为捐赠。将这份捐赠以麦迪文的名义进行，我将确保你获得公正的奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41007, '我丈夫维纳和我一直在寻找方法帮助海加尔山日益严重的问题。稀有材料褪色的梦境碎片变得越来越难找，不久后可能会绝迹。如果你能给我带来一枚褪色的梦境碎片，我会为你的努力给予丰厚的奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41027, '<巨豹之灵看起来对你产生了强烈的好奇心>$B$B我感受了到你天生的使命，一种来自你本真的力量。我有一项任务交给你，它将考验你的智慧和韧性。费伍德森林中有一个叫做暗影堡的地方，曾经是德鲁伊的巢穴，但现在被燃烧军团所侵扰。这个要塞里有一件对我来说最重要的神器，洛雷什之牙。暗影堡深处挥之不去的腐蚀气息已经将洛雷什的灵魂变成了疯狂的模样，希望你能够结束它的痛苦。$B$B向我展示你的勇猛，并把这件神器带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41087, '在古老传说的低语中，有关麦迪文之塔上游的故事展开了——这是一个神圣的避风港，曾经守护着守护者的深奥智慧。可惜的是，通往这座圣殿的通道已经随着时间的推移而消失，塔楼现在年久失修。坐落在上部的图书馆已被封锁，远离凡人。$B$B然而，在命运的浪潮中，希望在黑暗中闪烁。如果你能找到一种方法来突破上卡拉赞的守卫屏障，那么就有一个机会——一个机会——这本珍贵书籍的原封不动的副本就藏在它的深处。您所寻求的秘密可能隐藏在神圣的大厅中，隐藏在时间的破坏中，等待像您这样坚定的探索者发现。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41094, '<奇立简单地阅读了这封信，然后对自己点点头>$B$B明白了。$B$B你的故事对目前的情况有所帮助。是时候消灭这些恶魔了。他们已经远远超过了处决日期。$B$B需要你削弱他们的主力步兵。如果任务对您来说难以处理，请带上朋友。也请务必与特拉克纳尔交谈。他可能也有事要你做。$B$B我们的祖先和信仰可能不同，但我们保卫海加尔的承诺是相同的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41095, '周一，我遇到了一个与恶魔无关的问题。这是我的部落……他们中的大多数人都疯了。事情发生的时候，我们的代言人在梦中被神灵联系，并被告知要在翡翠圣殿入口附近用水塑造梦之魔精。当时我正在与恶魔战斗，但当我回来时，我自己的部落攻击了我，并称自己为“影灭部族”。他们已经陷入疯狂，但我相信，如果腐败的根源被根除，我的人民就能得救。杀死发动这场邪恶的军阀汉森托，并找到议长甘霍塔，他就是拥有梦之魔精的人。您可以在海加尔西部的祖尔哈萨找到它们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41098, '您好，$c，我注意到我收到了一封专门向您询问的信。它来自加基森的一个侏儒。$B$B他们被称为瑞亚斯。去找她，看看她想要什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41099, '$c 万岁，我有消息要告诉你。$B$B我们收到了有人专门向你询问的一封信。它来自加基森的一个侏儒。$B$B他们被称为瑞亚斯。我们被要求通知您，如果您有空，您应该去那里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41101, '你好$c。我们收到一封信，要求我们送你去东瘟疫之地。这封信来自驻扎在那里的一名德鲁伊。他们的名字是“莱茵”，可以在圣光之愿教堂找到他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41102, '问候$c。看起来你是时候重新开始做生意了。$B$BA 巴尔莫丹周围贫瘠之地的某个凯科斯·击王正在寻找“他值得信赖的伙伴”。他保证会有机会发大财。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41103, '你好$c，希望你今天过得愉快。我有消息要告诉你。某个托宝·光链正在寻求您的帮助。他提到，他的科学事业再次需要您的宝贵帮助。去巴尔莫丹寻找他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41104, '你好$c，看来你的搭档凯科斯·击王又来找你了。他说所有的事情都已经准备好了，他希望你能在场见证他的伟大时刻。在贝尔莫丹的贫瘠之地找到他。毕竟你是贵宾。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41105, '啊，是的，你好。我们还有一封信给你。很显然，你在巴雷斯的一些研究中发挥了重要作用。你的朋友托宝·光链请求你作为他的研究成果的主宾出席！最好别让他等着，嗯？你会在巴尔莫丹附近找到他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41112, '我已经被这种可悲的研究所困扰太久了。莫拉娜也没有让我的处境变得更轻松。我知道我们必须以某种方式在没有他的书的情况下揭开乌尔的秘密，但是——在烈火中我们怎么能做到这一点？$B$B最后我听说，部落的被遗忘者从席瓦莱恩城堡夺走了这本书——我担心我们可能会永远失去它。不过，我仍然抱有希望。沙德摩尔旅店里有一个女孩，声称自己是通过跳过吉尔尼斯城的城墙逃离的。抛开我的疑虑不谈，她实际上卖给了我一些有用的信息。很可能吉尔尼斯市的图书馆藏有一本《乌尔之书》。如果您能为我取回它，$B$B将不胜感激。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41113, '我不喜欢质疑老板，但我认为他已经开始失去理智了。我们注定要成为小偷，但金钱、宝藏、偷窃、抢劫和掠夺的快乐和冲动在哪里？$B$BI 无法说服黑刺让我和其他一些强盗袭击这座城市，但你多一点余地。我需要你做的就是前往吉尔尼斯市的图书馆并偷走米娅·格雷迈恩的肖像。我们将瓜分战利品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41120, '是的，小伙子！你听说过传说中的黎明石矿石吗？这是一个史诗般的故事，就是这样！用于在第二次战争期间为我们勇敢的圣骑士打造盔甲。那些确实是辉煌的日子！$B$B但是让我告诉你，这是一个稀有的发现，它确实如此！在这个广阔的世界中，只有一个地方可以挖掘它——隐藏在吉尔尼斯城下面的矿井。是的，下面有一个诅咒或者什么东西，某种神秘的东西把这种珍贵的矿石带到了地表。从我父亲的胡子来看，我不认为我会想知道它的真实本质。$B$B你看，格雷迈恩之门再次打开，吉尔尼斯的政治混乱已经留下了这一点。我的可能被遗弃了。所以，我正在考虑为安德麦的客户收集它。如果你能为我拿到十二块黎明石矿石，我非常愿意与你分享一定比例的利润。现在，你们怎么说？我们有协议吗') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41121, '我是吉尔尼斯的焚木领主。正如你可能已经听说的那样，叛军已经控制了格雷迈恩之墙，现在它已经敞开，在我们的王国中掀开了新的篇章。我被反抗军派到这里来恳求暴风城的援助来支持我们的事业。$B$B然而，在这些紧迫的事情中，我必须谦虚地寻求你的帮助。在格雷迈恩宫廷接待众多宾客期间，一位名叫伊瑟顿·匹瑞诺德的男子为我们的大厅增添了光彩。这个人被许多人视为奥特兰克王位的合法继承人，如果他提供支持，他可能会对联盟产生不可估量的价值。$B$B我听到了窃窃私语，说哈鲁恩家族可能会把他囚禁在禁区里可怕的干岩矿坑这个地方。我恳请您开始在那里进行搜索，如果您发现有关这位尊敬的客人的任何信息，请立即将其回报给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41122, '听着，$c！我现在有一件非常紧急和严重的事情需要你的帮助！$B$B那些吉尔尼斯人已经走了，再次打开了他们的大门，给我们带来了很多麻烦。爆炸吧！现在他们的沿海炮台正在对我们的运输船进行猛烈攻击，使与幽暗城的贸易成为真正的痛苦！$B$BI 需要你照顾炮兵莱尔森。他是弗雷希尔要塞的恶棍，也是那些该死的大炮的指挥者。你也不敢忘记他的追随者——把他们全部处理掉！$B$B一旦你把他送到了伟大的彼岸，就回来找我。我们没有时间可以浪费。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41127, '我们坚定的矮人盟友最近在石爪山脉建立了一个古老的第三次战争前哨基地。他们的首领是我的老朋友怀特峰。我确信他会感谢你帮助联盟重新安置石爪。$B$B如果我没记错的话，这个前哨站叫做贝尔哈杜尔。要找到它，你必须穿过塔隆迪普山口，然后向南进入山脉。有一条通往前哨站的秘密路径。$B$B如果你找到了怀特峰，请向他致以最诚挚的问候。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41137, '<大法师哈利斯特仔细地梳理着厚厚的书卷，他的眼睛扫视着每一行，其专注力表明了数十年的研究和经验。经过几分钟的努力寻找，他终于抬起头苦笑着看着你。>$B$B啊，是的。范多尔。大约四年前，他来到了塞拉摩。事实上，拜访了吉安娜女士。但他并没有在这座城市停留太久。我想，对于像他这样的老人来说，这里太繁华了。$B$B根据我们的记录，范多尔在访问后不久购买了一艘小船。如果你相信的话，里面装满了重要的物资、食物，甚至种子。我想，他启航前往南方，寻求更安静的生活。如果你想找到他，海岸线将是你最好的选择。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (55009, '在搜索弗雷克司泰利考格的尸体和周围区域后，你没有发现你要取回的测量装置的迹象。您应该向盖兹托格·可鲁派普报告您的发现。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (55012, '就像你看到的一样，我的愚蠢的伐木机坏了，我还缺少修理它所需的零件！我还丢了我的生财……与我家乡人民沟通的途径！$B$B所以，我得请你帮我跑个小腿，好吗？$B$B应该很容易的。这个新地方，纳特说的他和其他人定居的地方，那里应该有你需要的一切。$B$B哦，别那样盯着我看，你比我更需要我的帮助，所以回到那里旅行应该不会太过分吧。$B$B别担心，我可以等待。给我一些灯油、铜管和魔尘，剩下的施法过程我来做。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (55028, '好吧，让我履行诺言，然后继续前进。我们本可以在更有利可图和有用的事情上花费更多时间。亮水的船员一直都在藏宝海湾里，我从他们第一次在那场烟花般的战斗之后的那个晚上就知道了。他们并没有很好地隐藏自己的身份或者是什么的，再加上我的联系人非常可靠，所以我们确认这一点。你会在藏宝海湾的下层找到他们，就在那个钓鱼老手维格希克待的地方。下次你再见到“船长”佩泽尔，告诉他我已经还他那个愚蠢的人情了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (55030, '看来佩泽尔和他的船员真的陷入了困境，但如果需要帮忙的话，这意味着你要去烦那些被称为血帆海盗的暴徒，但这方面，我是完全支持！我有很多线索，但我并不完全知道谁在领导着追捕亮水船员的行动。话虽如此，但我知道有人可能知道。藏宝海湾外有一名我认识很久的线人，因为与海盗有关系，我把他们赶出了城市，但我保住了他们的脑袋，他们欠我一个人情。如果他们知道人情世故的话，他应该能帮助你一手。找到那名背叛血帆的家伙，告诉他们里维加兹在询问。一旦你得到了那些信息，告诉亮水的船员，他们可以自行决定怎么处理。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70000, '法师区总是那么安静，不是$N吗？好吧，当然，如果你要忽略那个强烈要求拜访蓝色隐士的呼唤的话。你已经成长为一名非常有能力的法师，许多人低声谈论你的名字，有些人散布关于你的谣言。$B$B因此它到达了一个非常不可能的家伙，我会告诉你不要接近，但毕竟这是你的决定.$B$B坐在艾萨拉的塔顶上，有一位大法师听说了你的成长和名字，并希望亲自见到你。众所周知，克希雷姆会收收学徒，如果他们发现学徒足够值得他的教导，也许这与此有关。$B$BI 建议你小心，这个人非常危险。要到达他的塔楼，你必须找到他的学徒萨纳斯，众所周知，他是一个非常快乐和愉快的精灵。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70033, '“这是$N，你迄今为止最危险的任务，但我非常确信你会成功。$B$B你展现出了我很久没有见过的勇气，愿祖先指引你的脚步，保佑你平安归来。$B$B你有我的祝福和祖先的庇护。$B$B你站立的地方曾经站着一位伟大的战士，你也将走在他的脚步中，带着你心中的骄傲杀死他们！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70034, '诺沃克没有条件出去寻找传家宝，但我担心他可能会在完全痊愈之前尝试冒险。$B$B如果你能找到他留下的长矛的任何痕迹，诺沃克和我都会非常感激。$B$B东边的恶魔是你找到它的最佳选择，所以快点走吧！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70040, '我从未放弃过我的梦想，$N，我的使命即使在死亡中仍然存在，我活着是为了锻造和帮助我们骄傲的士兵保护自己，唉，你也会帮助我做到这一点。$B$B我们的人面临着银松森林的危险，最后的天灾，达拉然的魔法师和阿鲁高召唤到我们土地上的肮脏野兽。$B$B我想象着瑟伯切尔供应不足的样子，给他们带来这些物品。$B$B交付后，您预计将获得一套新盔甲，因此您也将准备好面对我们的敌人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70053, '$N，蛇颈龙出问题了。他们离开了藏身之处，吃掉了湖里所有的鱼！$B$B一段时间以来，我们当地的捕鱼业务因此一直在下降。恐怕我们将不得不接受这样一个事实，即我们必须剔除它们的数量，以便我们能够保持一定的平衡。$B$B嘿，这些美丽的生物与我们世世代代共享湖泊，所以我们必须对它们采取如此极端的行动，这让我很痛苦。$B$B我只期望一个外来人去做我们不能做，也不愿意做的事情。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70056, '你给了我和暮色森林的人们一个很大的帮助，我希望你向我的指挥官报告。$B$B我非常确定她会喜欢听到你对抗迪菲亚的成功，而且她可能还会有另一个任务交给你$B$B把这张羊皮纸交给指挥官阿尔泰娅·埃伯洛克。她驻扎在市政厅前面，所以很难错过她。$B$B哦，还有，$N，谢谢。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70057, '我听说斯温在乌鸦岭墓地附近的一个棚屋里避难。我担心他充满了后悔和愤怒，无论是对他自己还是对那些从他那里夺走一切的人。$B$B考虑到我们在他失落的家园废墟中发现了他的这把铲子，我觉得应该把它还给他。$B$B请把这个还给斯温。要小心，他可能会因为看到它而松了一口气，也可能会痛苦地把它掰成两截。谁知道呢。$B$B再次感谢您所做的一切。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80100, '好的，伙计，听着！我知道这是你在风险投资公司的第一份工作，所以我会慢慢地跟你说。$B$B我们来这里是为了找到一笔有价值的宝藏，你明白吗？据说价值比安德麦里一半的珠宝还要多，老板迫不及待地想得到它。上次他派遣的工作人员什么消息都没有回来。$B$B这帮小偷以为他们可以从老板手中逃脱吗？你最好相信，他会追踪他们并把他们抓回来。老板说不要空手而归，所以我们开始工作吧。$B$B我们的飞行器在下来的时候损坏了一些零件，但幸运的是，上次的工作人员似乎把他们的机器人留在了这里。去四处跑一跑，从它们身上收集一些小玩意，好吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80103, '嗯，我想我们明白了为什么精灵会在这里。前方整个森林都着火了！而且肯定是地精做的。$B$B没有其他人会用那种能燃烧这么久的油！那是安德麦的货，孩子。侏儒不可能得到它。我不知道这个地方是怎么回事，但我不喜欢它。$B$B去那里带回一些油。也许你会找到一些关于我们到达这里之前发生的事情的线索。如果没有，至少我们自己的油供应又增加了！“') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80107, '我现在不羡慕你，小伙子。听着，那些奇怪的秃鹫并不是树林里最糟糕的东西。其他一些伤痕累累的人四处张望，他们发现了一个坟墓，看起来是来自奥达曼的坟墓。$B$B他们试图靠近，但他们听到里面传来某种邪恶的声音。这些家伙以前参加过老板的一些“有说服力”的采访，他们从来没有听过这样的声音。说着，它在山上回荡着不自然的，仿佛是从不存在的树木上弹下来的。$B$B，我会和精灵战斗。我要和植物怪物战斗。我会和我们自己的爆破坦克作战！但我不是在惹一些古老的被诅咒的坟墓。我希望你去那里，找出那些门后面的东西，并处理它。为我做这件事，你和我就是一辈子的密友。你将来甚至可能会有晋升的机会。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80120, '嘿你！是的，我在和你说话，朋友！$B$B我整天都在捡我们船员的垃圾，我真的可以休息一下。$B$B我说，你清理一会儿怎么样？$B$B我会在树荫下打个盹。当我醒来时，我希望这个地方一尘不染。$B$B现在开始工作！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80353, '谁会想到让一个食人魔砍一些木头，最后他会忘记捡起来？$B$B笨蛋蛮子开始砍啊砍，但当他回来时，他没有带任何东西回来！$B$B我会自己去取，但我正忙着呃……什么。那么你为什么不这样做呢？$B$B这里的人们尊重劳动人民，你会得到与行动价值相称的报酬，小伙子。$B$B去捡几捆木材带回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80723, '所以这个药水是血色计划的关键。它乏味、粗糙，却又强效得令人作呕。$B$B我自己并不涉足炼金术的低级工艺。幸运的是，，我们女王的皇家药剂师们更擅长琢磨蒸馏器和研磨草本植物。$B$B去药剂师那里，找到药剂师茨温克并向她展示你的发现。她是我的人。$B$B去，动作要快，保持谨慎。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (6961, '和冬天爷爷谈谈；他在奥格瑞玛烟林牧场商人区旁边。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7782, '回到暴风城的英雄谷跟艾法希比元帅谈谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8730, '干掉奈法利安并拿到红色节杖碎片。把红色节杖碎片带给塔纳利斯时光之穴门口的阿纳克洛斯。你必须在一个半小时之内完成这个任务。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8740, '干掉暮光掠夺者莫娜和5个暮光掠夺者。当任务完成之后向唤风者梅恩·长角报告。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39001, '探索古博拉采掘场的洞穴。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39991, '杀死瓦罗卡尔中尉和与他一起巡逻的两名激流堡骑兵。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39995, '把偷来的武器计划带到十字路口的纳加尔·死眼。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39996, '把一根长长的科卡尔骨头带到十字路口的纳加尔·死眼') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39997, '与雷霆崖的比尔吉特·克兰斯顿交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40020, '在祖尔拉萨兹废墟中找到尹多的项链。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40025, '收集5个活根草，10个坚固的石头，和3个野钢花，并把它们带给演讲者甘基。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40027, '前往迷雾山谷，寻找桑维的护身符。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40030, '找到并杀死诺博鲁的棍棒，并将诺博鲁的棍棒带到玛格图尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40031, '为马萨特·坦德收集10个锯齿皮革。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40032, '为珊弗科拉收集6个缠结的精华和一个沼泽鱼眼。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40036, '从恶鞭侍从收集20个侍从图章到破碎海岸。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40038, '杀死呣啦哇啦，把他的头带给拉沙尔夫人。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40039, '找到埋藏的瑞思雷斯潮汐权杖，并将其带给潮汐女主人瑞舍尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40040, '与吉格诺·麻须交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40041, '为吉格诺·麻须获得一个Mistwing喇叭，以证明您的忠诚。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40044, '从雷瑟斯圣所附近的分析器53G上面取回分析芯片。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40045, '与罗利·齿钟讨论飞行日志。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40046, '前往东部的停机坪，从丁考·托格派普获取飞行日志，然后将飞行日志归还给吉格诺·麻须。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40047, '找到并将吉格诺的报告带给工匠大师欧沃斯巴克。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40048, '把工匠大师欧沃斯巴克的回应带给吉格诺·麻须。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40057, '回收吉格诺·麻须的工匠火花应答器。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
