INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40299, '为了创造光明使者的护肩，你需要将以下物品带回玛雷弗斯·暗锤：1张原始兽皮；10块奥金条；8个正义之球；5个信仰奖章。你还需要为该物品的制作支付50枚金币。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (40943, '为了结束龙类在吉尔尼斯的腐蚀，请为吉尔尼斯城拉文郡的大法师奥勒留斯消灭拉文郡摄政夫人西莉亚和摄政王莫蒂默。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41105, '寻找巴雷斯的巴尔莫丹附近的托宝·光链。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41121, '查找有关伊瑟顿·匹瑞诺德的任何信息。有传言说他被囚禁在吉尔尼亚斯的干岩矿坑。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (70040, '巴兹尔·弗莱伊希望你带着4个铭文铜腰带和4把重铜战锤去找银松森林的艾德温·哈里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40001, '啊，兄弟，煞古让你去拿他的草药？米什基想尽快把它寄出去，但你看，我们遇到了一点问题。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40022, '他将加入甘图，直到我死的那一天，$C。他们两个将永远装饰我的腰带，并成为战胜威瑟巴克和与部落建立新友谊的象征。你做得很好，$N。你的事迹将被我的人民永远铭记。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40027, '桑维的护身符对我来说意义重大，局外人。桑瓦人曾经是外域的一个大部落。可悲的是，我是唯一剩下的。让我准备好与失踪的人的通讯。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40048, '诺莫瑞根……堕落？没有更多的工匠火花应答器？！我们回不去了。回去没有意义。与诺莫瑞根相比，小炉镇听起来就像是一个贫民区。我们将把亚麻须变成新的诺莫瑞根。我们只是需要时间！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40157, '原始主义者琼吉轻轻叹了一口气，点了点头。>$B$bi知道必须做什么来收集这些，兄弟。这对我的人民来说是必要的，最终，伤口可能会再次愈合。谢谢你所做的一切。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40161, '出色的工作。如果没有哈祖叶，制作我们的许多食谱就会困难得多，也很难简单地放松，兄弟。把这个作为对我感激的回报。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40184, '塞瑞尔死了，你已经实现了对他的承诺。他只剩下一袋你捡来的硬币。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40196, '已经完成了，你已经为我们每个人报仇了。我不知道该怎么感谢你把他打倒，如果命运不是这样，如果他诚实行事，信守诺言，也许我们会回家。$B$Bit不是什么值得关注的东西，但我们卡尔科尔将在世界上找到自己的位置。你在我们的社区中赢得了尊重，恢复了我们的精神，我祝你未来一切顺利。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40197, '这是一场悲剧，整个灰谷都发生了这样的事情。这一天，森林确实失去了一个聪明的头脑，枯萎成了一种徘徊在树林中的肮脏的疯狂。$B$B别难过，对于老灰爪来说，这种命运是无法避免的，他对他自己和他身边的所有人都是一个危险。我祈祷他的灵魂能超越艾露恩，并被永恒地守护。$B$B虽然我很讨厌这样的结局，但我还是要感谢你，因为灰爪不是他自己，如果他在的话。他会请求这样的仁慈，让他从疯狂中解脱出来。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40219, '那些愚蠢的海盗认为他们很聪明，接管了那个矿，现在看看他们，死了！微不足道的$R为我做了好事，我奖励好的工作，这里，拿着这个，你现在是莫尔奥格的正式雇佣兵！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40232, '那么，它完成了吗？大主教一直是我的朋友，他的信念和话语一直是真实的。$B$B这个卷轴将继续指导我们在这里的行动，并保证我们在悲伤卫士中的安全。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40242, '为什么要看这些美女？这些贝壳当然可以用来做各种各样的事情，再次感谢，难怪吉格诺在你身上看到了好东西！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40244, '艾尔达拉转移宝珠是同类中的一种，非常罕见，如果没有我的研究能力，与艾萨拉最后的守护者的通信都被篡改了。你能找到它，我感激不尽。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40258, '它已经消失了很久，现在它就在这里！$B$B你做得很好，我从来没有想过我会再次看到它，它就在我的手中。也许现在烬腹可以成为最强的食人魔了！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40266, '他想出了一个大胆的计划，我不会怀疑伯乌克会说出这样的话。但也许没有其他选择，我将开始研究一种灵丹妙药。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40856, '冒险家！我很高兴地通知您，阿尔法通道和储备泵通道的性能非常出色，运行效率约为87%。不，等等，88%！考虑到诺莫瑞根遭受的破坏，这确实是一个令人欢迎的惊喜。$B$B 对于您为帮助我们恢复该设施所提供的宝贵帮助，我无法表达足够的谢意。没有你们的努力，我们不可能取得如此大的进步。$B$B 为了表达我们的感激之情，请接受我们所有人在回收设施提供的这份谦卑的奉献。愿它对您未来的努力有所帮助。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40942, '<奥蕾利斯沉默片刻，将宝石的能量与奥法之泉融合。随着时间的流逝，他发出一声响亮而沉重的叹息。>我的担忧成为现实，我的推断被证实正确。普瑞斯托领主或许一直都是一只伪装成人类的龙类。我确信那些来替代他的人也是如此。哈鲁恩家族是在普瑞斯托到达吉尔尼斯时崛起的贵族家族。雷蒂西莉亚和莫蒂默领主是格雷迈恩国王的摄政者，代表国王执事。黑龙的影响深深渗透到吉尔尼斯，他们似乎长久以来一直在谋划着这洗的冲突。无辜者的死亡和这片土地的腐化，都是他们造成的。他们必须被阻止。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41015, '上半部分和下半部分都在一起。我从未想过会看到它们在一起。<汉瓦稍作整理>这些护腕已经被带到了一起，如今它们又重新连接在一起。我被诅咒永远保护着这些物品，但看来你更有机会履行我的使命。守护好这个护腕，确保它不会落入邪恶之手。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (55017, '哦，我难道没有派你去过艾萨拉吗？别告诉我你整个时间都在酒馆里呆着！这是盖兹托格送来的？我本以为他拿着火花之水的钱跑了，我正准备叫我的人去给他一个真正的问候。不过，他似乎至少找到了一些有希望的结果。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (70034, '这把长矛为我的家人服务了好几代人。$B$B我很伤心，因为我是那个把它终结的人，并给我的部落带来了耻辱。$B$B<诺沃克从他巨大的鼻孔深吸一口气，微笑着让空气出来。>$B$B别这么难过，我最新结识的朋友，你对我的帮助比你知道的要多。这不是结束，而只是开始。$B$B我会重新锻造刀片并使其更加坚固，毕竟即使你切开鹰的翅膀，他的喙也一如既往地危险。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (70053, '你是说它们的尺寸更小？这可以解释它们的饥饿感。$B$B然而，什么会让它们这么早离开巢穴，为什么它们全部离开巢穴？$B$B<瓦格思考了一会儿，然后转向你。>$B$B这是说好的报酬。我会进一步调查。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (70057, '你拿着什么，$C？$B$B哦，你从哪里找到的？$B$B这是我父亲几年前我们在农庄工作时给我的铲子。它对我很有帮助，让我想起了他。$B$B回忆起更美好的时光。$B$B<斯温盯着铲子，把它递还给你。>$B$B你给我带来这个是一片好心，$N，但我已经用不上了。$B$B随你怎么处置。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (80291, '如果你没有找到泰洛斯，那么这意味着那个骷髅就是他。嗯，无所谓。还有关于黑色粘液从井水中涌出的事情？所以他们是对的，非常有趣。$B$B不管怎样，感谢你在这里的帮助，但我想现在是你离开的时候了。我还有研究要做，你应该把我们在这里发现的情况告诉奥术师，不是吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (80723, '我的名字是金格，$c.$B$B告诉我你带来了什么，我会尽力帮助你，如果这是我主人的命令。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40027, '桑维的符咒必须恢复，局外人。动作要快。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40168, '弗雷克利夫派你来的？我很久没和他说话了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40218, '玻璃眼可能有强大的，神奇的力量，一定要保持头脑清醒。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40254, '在厄运之槌中使用的能量真的很迷人，我从这里就能感受到。我相信这将是我们履行守护者誓言的唯一机会。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40266, '你和伯乌克先知谈过了吗？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40288, '加德纳尔要塞是军团在费伍德森林最强大的堡垒，把他们打倒。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (60030, '我只要看着你就知道，我的朋友，你对时尚有自己独到的眼光！不要试图隐藏这些优秀的想法，我可以在你大胆的搭配中看到它，我不会像其他庸人那样狗眼看人低。我可以为您提供一些可以用来幻化的幻化币，而你则需要为我带来一些充满操作性空间、具有艺术价值的原料，这样，我们就可以一起可以点燃时尚界！这是我需要的物品清单，请确保它们完好无损且质量上乘。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (60031, '我只要看着你就知道，我的朋友，你对时尚有自己独到的眼光！不要试图隐藏这些优秀的想法，我可以在你大胆的搭配中看到它，我不会像其他庸人那样狗眼看人低。我可以为您提供一些可以用来幻化的幻化币，而你则需要为我带来一些充满操作性空间、具有艺术价值的原料，这样，我们就可以一起可以点燃时尚界！这是我需要的物品清单，请确保它们完好无损且质量上乘。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
