INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (60036, '今天我给你带来了些很棒的东西！传闻说居住在斯坦索姆的一些狂热的十字军携带着充满神圣力量的球体，它们被称为正义宝珠。此外我需要的另一个珍宝是无瑕的德莱尼水晶球，据说被诅咒之地每一个可怕的恶魔都有可能携带。只要你能给我带来这些奇珍异宝，我就给你3枚幻化币没有它们我根本无法完成我的最新设计！') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);
INSERT INTO `locales_quest` (`entry`, `ObjectiveText1_loc4`) VALUES (40132, '让托宝·光链打开分析仪X-51并观察会发生什么。') ON DUPLICATE KEY UPDATE `ObjectiveText1_loc4` = VALUES(`ObjectiveText1_loc4`);
INSERT INTO `locales_quest` (`entry`, `ObjectiveText1_loc4`) VALUES (40133, '让托宝·光链打开分析仪X-51并观察会发生什么。') ON DUPLICATE KEY UPDATE `ObjectiveText1_loc4` = VALUES(`ObjectiveText1_loc4`);
INSERT INTO `locales_quest` (`entry`, `ObjectiveText1_loc4`) VALUES (40266, '与伯乌克交谈') ON DUPLICATE KEY UPDATE `ObjectiveText1_loc4` = VALUES(`ObjectiveText1_loc4`);
